+        const ex = e.x + Math.cos(a) * range;
+        const ey = e.y + Math.sin(a) * range;
+        const hit = g.map.raycast(e.x, e.y, ex, ey, range);
+        points.push(hit ? { x: hit.x, y: hit.y } : { x: ex, y: ey });
