+
+  drawParticles() {
+    const ctx = this.ctx;
+    const g = this.game;
+    for (const p of g.particles) {
+      if (!this.inView(p.x, p.y, 90)) continue;
+      const life = clamp(p.life / p.max, 0, 1);
