import { openPage } from './cdp.mjs';

const page = await openPage('http://localhost:8123/index.html');
const shot = (n) => page.screenshot(`/tmp/opencode/shot-${n}.jpg`, 55);
await page.wait(2500);
console.log('STATE', await page.evaluate('window.game ? window.game.state : "NO GAME"'));
console.log('MENU VISIBLE', await page.evaluate('!document.getElementById("menu").classList.contains("hidden")'));
console.log('LOGS', JSON.stringify(page.drain(), null, 1));
await shot('01-menu');
await page.click('#btn-play');
await page.wait(500);
console.log('AFTER PLAY', await page.evaluate('window.game.state'));
await shot('02-deploy');
await page.wait(1200);
console.log('NOW', await page.evaluate('window.game.state'), 'hp', await page.evaluate('window.game.player?.hp'));
await shot('03-play');
// fire at an enemy: aim at screen center-right
await page.send('Input.dispatchMouseEvent', { type: 'mouseMoved', x: 900, y: 400 });
await page.send('Input.dispatchMouseEvent', { type: 'mousePressed', x: 900, y: 400, button: 'left', clickCount: 1 });
await page.wait(700);
await page.send('Input.dispatchMouseEvent', { type: 'mouseReleased', x: 900, y: 400, button: 'left', clickCount: 1 });
await page.wait(300);
console.log('SHOTS', await page.evaluate('window.game.run.shots'), 'BULLETS', await page.evaluate('window.game.bullets.length'));
console.log('HUD AMMO', await page.evaluate('document.getElementById("ammo-mag").textContent'), '/', await page.evaluate('document.getElementById("ammo-reserve").textContent'));
console.log('LOGS2', JSON.stringify(page.drain(), null, 1));
await shot('04-fire');
// pause
await page.send('Input.dispatchKeyEvent', { type: 'keyDown', key: 'Escape', code: 'Escape', windowsVirtualKeyCode: 27 });
await page.send('Input.dispatchKeyEvent', { type: 'keyUp', key: 'Escape', code: 'Escape', windowsVirtualKeyCode: 27 });
await page.wait(500);
console.log('PAUSED', await page.evaluate('window.game.state'), 'panel', await page.evaluate('window.game.ui.panelKind'));
await shot('05-pause');
await page.evaluate('window.game.ui.closePanel(true); window.game.resume();');
await page.wait(300);
// test armory panel from menu
await page.evaluate('document.getElementById("hud").classList.add("hidden"); document.getElementById("menu").classList.remove("hidden"); window.game.state="menu"; window.game.menuKey=""; window.game.refreshMenu(); window.game.ui.openPanel("armory");');
await page.wait(600);
console.log('ARMORY PANEL', await page.evaluate('window.game.ui.panelKind'), 'body len', await page.evaluate('document.getElementById("panel-body").innerHTML.length'));
