import { openPage } from './cdp.mjs';

const page = await openPage('http://localhost:8123/index.html');
await page.wait(2000);
console.log('VIEWPORT', await page.evaluate('[innerWidth,innerHeight]'));
console.log('FOOTER', await page.evaluate(`(() => { const r=document.querySelector('.menu-footer').getBoundingClientRect(); return {top:r.top,bottom:r.bottom,h:r.height, scrollH:document.querySelector('.menu-screen').scrollHeight, clientH:document.querySelector('.menu-screen').clientHeight}; })()`));
console.log('MAIN', await page.evaluate(`(() => { const r=document.querySelector('.menu-main').getBoundingClientRect(); return {top:r.top,bottom:r.bottom,h:r.height}; })()`));
// Skirmish full flow
await page.evaluate('window.game.startSkirmish()');
await page.wait(1300);
console.log('SKIRMISH', await page.evaluate(`({state:game.state,wave:game.wave,enemies:game.enemies.length,mode:game.mode})`));
await page.evaluate(`(() => { const g=game; for (const e of g.enemies) if(!e.dead) g.damageEnemy(e, 9999, 0, true, e.x, e.y, true); })()`);
await page.wait(300);
console.log('WAVE PENDING', await page.evaluate(`({wave:game.wave,pending:game.wavePending,t:game.waveTimer})`));
await page.screenshot('/tmp/opencode/shot-20-skirmish-clear.jpg', 55);
await page.wait(4200);
console.log('WAVE 2', await page.evaluate(`({wave:game.wave,pending:game.wavePending,enemies:game.enemies.filter(e=>!e.dead).length, grenades:game.player.grenades, hp:game.player.hp})`));
await page.screenshot('/tmp/opencode/shot-21-skirmish-wave2.jpg', 55);
// die
await page.evaluate('window.game.damagePlayer(9999, 0, game.player.x, game.player.y)');
await page.wait(500);
console.log('DEAD', await page.evaluate(`({state:game.state,panel:game.ui.panelKind,results:game.pendingResults?.success,wave:game.pendingResults?.wave})`));
await page.screenshot('/tmp/opencode/shot-22-failed.jpg', 55);
// retry skirmish
await page.evaluate('game.restartMission()');
await page.wait(1300);
console.log('RETRY', await page.evaluate(`({state:game.state,wave:game.wave,skirmish:game.skirmish})`));
// grenade + barrel test
await page.evaluate('game.abortMission()');
await page.wait(800);
await page.evaluate('game.startMission(0)');
await page.wait(1300);
await page.evaluate(`(() => { const g=game; g.player.grenades=3; })()`);
await page.evaluate('game.throwGrenade()');
await page.wait(1600);
console.log('GRENADE EXPLODED', await page.evaluate(`({grenades:game.grenades.length,particles:game.particles.length})`));
console.log('ERRORS', JSON.stringify(page.drain().filter(e=>e.level === 'exception' || e.level === 'error')));
await page.close();

