import { openPage } from './cdp.mjs';

const page = await openPage('about:blank');
await page.send('Emulation.setDeviceMetricsOverride', { width: 844, height: 390, deviceScaleFactor: 2, mobile: true, screenOrientation: { type: 'landscapePrimary', angle: 90 } });
await page.send('Emulation.setTouchEmulationEnabled', { enabled: true, maxTouchPoints: 5 });
await page.send('Emulation.setUserAgentOverride', { userAgent: 'Mozilla/5.0 (iPhone; CPU iPhone OS 17_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/17.0 Mobile/15E148 Safari/604.1' });
await page.send('Page.navigate', { url: 'http://localhost:8123/index.html' });
await page.wait(3000);
console.log('VIEW', await page.evaluate('[innerWidth,innerHeight,devicePixelRatio]'), 'touch', await page.evaluate('game.isTouch'), 'class', await page.evaluate('document.body.className'));
await page.screenshot('/tmp/opencode/shot-30-mobile-menu.jpg', 55);
console.log('LAYOUT', await page.evaluate(`(() => { const p=document.querySelector('.panel'); return {pl:p.getBoundingClientRect().width, vw:innerWidth}; })()`));
await page.click('#btn-play');
await page.wait(1500);
await page.screenshot('/tmp/opencode/shot-31-mobile-play.jpg', 55);
console.log('HUD', await page.evaluate(`({state:game.state, touch:game.isTouch, hudHidden:document.getElementById('hud').classList.contains('hidden'), actions:getComputedStyle(document.querySelector('.hud-actions')).display, sticks:document.getElementById('stick-move').className})`));
// touch drag on left side => move; right side => aim/fire
await page.send('Input.dispatchTouchEvent', { type: 'touchStart', touchPoints: [{ x: 220, y: 290, id: 1 }] });
await page.send('Input.dispatchTouchEvent', { type: 'touchMove', touchPoints: [{ x: 260, y: 270, id: 1 }] });
await page.wait(400);
await page.send('Input.dispatchTouchEvent', { type: 'touchEnd', touchPoints: [] });
await page.send('Input.dispatchTouchEvent', { type: 'touchStart', touchPoints: [{ x: 640, y: 290, id: 2 }] });
await page.send('Input.dispatchTouchEvent', { type: 'touchMove', touchPoints: [{ x: 720, y: 250, id: 2 }] });
await page.wait(900);
console.log('SHOTS', await page.evaluate('game.run.shots'), 'moved', await page.evaluate('[Math.round(game.player.x),Math.round(game.player.y)]'), 'joy', await page.evaluate(`document.getElementById('stick-aim').className`));
await page.screenshot('/tmp/opencode/shot-32-mobile-sticks.jpg', 55);
await page.send('Input.dispatchTouchEvent', { type: 'touchEnd', touchPoints: [] });
// pause button
await page.click('.pause-btn');
await page.wait(500);
console.log('PAUSE PANEL', await page.evaluate(`({state:game.state,panel:game.ui.panelKind})`));
await page.screenshot('/tmp/opencode/shot-33-mobile-pause.jpg', 55);
// rotate portrait
await page.send('Emulation.setDeviceMetricsOverride', { width: 390, height: 844, deviceScaleFactor: 2, mobile: true, screenOrientation: { type: 'portraitPrimary', angle: 0 } });
await page.wait(800);
console.log('PORTRAIT HINT', await page.evaluate(`({hidden:document.getElementById('rotate-hint').classList.contains('hidden'),text:document.getElementById('rotate-hint').textContent})`));
await page.screenshot('/tmp/opencode/shot-34-mobile-portrait.jpg', 55);
console.log('ERRORS', JSON.stringify(page.drain().filter(e=>e.level === 'exception' || e.level === 'error')));
await page.close();

