import { openPage } from './cdp.mjs';

const page = await openPage('about:blank');
await page.send('Emulation.setDeviceMetricsOverride', { width: 844, height: 390, deviceScaleFactor: 2, mobile: true, screenOrientation: { type: 'landscapePrimary', angle: 90 } });
await page.send('Emulation.setTouchEmulationEnabled', { enabled: true, maxTouchPoints: 5 });
await page.send('Page.navigate', { url: 'http://localhost:8123/index.html' });
await page.wait(2500);
await page.evaluate('localStorage.clear()');
await page.send('Page.reload');
await page.wait(2500);
console.log('MENU MEASURE', await page.evaluate(`(() => { const q=s=>document.querySelector(s)?.getBoundingClientRect(); const sc=document.querySelector('.menu-screen'); return {
  vh:innerHeight, scrollH:sc.scrollHeight, nav:q('.nav-grid'), card:q('.mission-card'), play:q('#btn-play'), footer:q('.menu-footer'), h1:q('.hero h1'), tag:q('.tagline'),
}; })()`));
await page.screenshot('/tmp/opencode/shot-40-mobile-menu2.jpg', 55);
await page.click('#btn-play');
await page.wait(1600);
console.log('HUD MEASURE', await page.evaluate(`(() => { const q=s=>document.querySelector(s)?.getBoundingClientRect(); return {
  zoom:game.renderer.camera.zoom, vh:innerHeight, vw:innerWidth,
  actions:q('.hud-actions'), weapon:q('.weapon-hud'), pause:q('.pause-btn'), mini:q('.minimap-wrap'), objective:q('.hud-objective'), toast:q('.hud-toast'), toastShow:document.querySelector('.hud-toast').className,
}; })()`));
await page.screenshot('/tmp/opencode/shot-41-mobile-play2.jpg', 55);
await page.evaluate(`(() => { const g=game; const e=g.enemies[0]; g.player.x=e.x+120; g.player.y=e.y; g.renderer.resetCamera(); })()`);
await page.wait(700);
await page.screenshot('/tmp/opencode/shot-42-mobile-combat2.jpg', 55);
console.log('ERRORS', JSON.stringify(page.drain().filter(e=>e.level === 'exception' || e.level === 'error')));
await page.close();

