  const out = {};
  for (const [k, s] of Object.entries({actions:'.hud-actions', weapon:'.weapon-hud', pause:'.pause-btn', mini:'.minimap-wrap', objective:'.hud-objective', toast:'.hud-toast', hudTop:'.hud-top', hudBottom:'.hud-bottom'})) {
    const r = document.querySelector(s)?.getBoundingClientRect();
    out[k] = r ? {x:Math.round(r.x),y:Math.round(r.y),w:Math.round(r.width),h:Math.round(r.height)} : null;
  }
  out.actionsDisplay = getComputedStyle(document.querySelector('.hud-actions')).display;
  out.actionsRows = getComputedStyle(document.querySelector('.hud-actions')).gridTemplateRows;
  return out;
})()`);
