.mission-card h2 { font-family: var(--display); font-size: clamp(22px, 2.3vw, 30px); letter-spacing: 0.06em; margin: 0 0 6px; font-weight: 700; }
.mission-card p { font-size: 11.5px; line-height: 1.55; color: var(--muted); margin: 0 0 14px; min-height: 2.9em; }
.card-stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px; padding: 10px 0; border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); margin-bottom: 12px; }
.card-stats div { display: flex; flex-direction: column; gap: 3px; }
.card-stats span { font-family: var(--mono); font-size: 7px; letter-spacing: 0.16em; color: var(--dim); }
.card-stats b { font-family: var(--display); font-size: 12px; letter-spacing: 0.06em; color: var(--text); font-weight: 600; }
.card-stats .threat { color: var(--red); letter-spacing: 0.08em; }
.card-stats .gold { color: var(--amber-bright); }
.btn-deploy {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 13px 16px;
  border-color: rgba(240, 162, 60, 0.35);
  background: rgba(240, 162, 60, 0.08);
  color: var(--amber-bright);
  font-size: 13px;
  letter-spacing: 0.22em;
}
.btn-deploy:hover { background: rgba(240, 162, 60, 0.16); }
.btn-deploy i { font-style: normal; font-size: 16px; }
.menu-footer {
  position: relative;
  z-index: 2;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding-top: 10px;
  border-top: 1px solid rgba(148, 163, 184, 0.1);
  flex: 0 0 auto;
}
.ticker { display: flex; align-items: center; gap: 14px; font-family: var(--mono); font-size: 8px; letter-spacing: 0.12em; color: var(--dim); overflow: hidden; white-space: nowrap; }
.ticker i { width: 3px; height: 3px; border-radius: 50%; background: var(--amber); opacity: 0.5; flex: 0 0 auto; }
.ticker span:first-child { color: rgba(52, 211, 153, 0.8); }
.build-tag { font-family: var(--mono); font-size: 8px; letter-spacing: 0.14em; color: var(--dim); flex: 0 0 auto; }

/* ------------------------------------------------------------------- hud */
.hud { pointer-events: none; z-index: 20; }
.hud::before {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgba(2, 5, 8, 0.55), transparent 16%, transparent 76%, rgba(2, 5, 8, 0.68));
}
.hud-top {
  position: absolute;
  top: calc(12px + var(--safe-top));
  left: calc(14px + var(--safe-left));
  right: calc(14px + var(--safe-right));
  display: grid;
  grid-template-columns: minmax(230px, 1fr) auto minmax(210px, 1fr);
  gap: 16px;
  align-items: start;
}
.hud-operator {
  display: flex;
  gap: 10px;
  align-items: stretch;
  background: linear-gradient(100deg, rgba(7, 12, 18, 0.86), rgba(7, 12, 18, 0.25));
  border-left: 2px solid var(--amber);
  padding: 8px 12px 8px 8px;
  width: min(330px, 100%);
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 10px), calc(100% - 10px) 100%, 0 100%);
}
.op-badge {
  position: relative;
  width: 46px;
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  background: rgba(240, 162, 60, 0.1);
  border: 1px solid rgba(240, 162, 60, 0.28);
  font-family: var(--display);
  font-size: 17px;
  letter-spacing: 0.04em;
  color: var(--amber-bright);
}
.op-badge i { position: absolute; bottom: 2px; right: 3px; font-style: normal; font-family: var(--mono); font-size: 6px; color: var(--dim); }
.op-bars { flex: 1; min-width: 0; }
.bar-label { display: flex; justify-content: space-between; align-items: baseline; font-family: var(--mono); font-size: 7px; letter-spacing: 0.16em; color: var(--dim); margin-bottom: 3px; }
.bar-label b { font-family: var(--display); font-size: 15px; color: var(--text); letter-spacing: 0.04em; }
.bar { position: relative; height: 7px; background: rgba(148, 163, 184, 0.1); overflow: hidden; margin-bottom: 3px; }
.bar i { position: absolute; inset: 0; transform-origin: left; transition: transform 0.18s ease; }
.hp-bar i { background: linear-gradient(90deg, #2dd4bf, #34d399); box-shadow: 0 0 10px rgba(52, 211, 153, 0.4); }
.hp-bar em { position: absolute; inset: 0; background: repeating-linear-gradient(90deg, transparent 0 18%, rgba(5, 7, 10, 0.8) 18% 19%); }
.armor-bar { height: 4px; }
.armor-bar i { background: linear-gradient(90deg, #38bdf8, #818cf8); }
.focus-line { display: flex; align-items: center; gap: 6px; margin-top: 5px; font-family: var(--mono); font-size: 6px; letter-spacing: 0.14em; color: var(--dim); }
.focus-meter { flex: 1; height: 3px; background: rgba(148, 163, 184, 0.12); overflow: hidden; }
.focus-meter i { display: block; height: 100%; width: 100%; background: var(--violet); transform-origin: left; transition: transform 0.2s linear; }
.focus-line b { color: var(--violet); font-weight: 500; }

.hud-objective { text-align: center; padding-top: 4px; min-width: 230px; }
.obj-kicker { font-family: var(--mono); font-size: 7px; letter-spacing: 0.24em; color: var(--amber); }
.obj-main { display: flex; align-items: center; justify-content: center; gap: 7px; margin: 3px 0 2px; }
.obj-diamond { width: 5px; height: 5px; background: var(--amber); transform: rotate(45deg); box-shadow: 0 0 8px var(--amber); }
.obj-main strong { font-family: var(--display); font-size: clamp(13px, 1.4vw, 17px); letter-spacing: 0.1em; font-weight: 600; text-shadow: 0 2px 8px rgba(0, 0, 0, 0.8); }
.obj-sub { font-family: var(--mono); font-size: 9px; letter-spacing: 0.12em; color: var(--muted); }
.obj-sub.live { color: var(--green); }
.hud-right { display: flex; flex-direction: column; align-items: flex-end; gap: 8px; padding-right: 44px; }
.minimap-wrap {
  position: relative;
  width: clamp(120px, 13vw, 190px);
  border: 1px solid rgba(148, 163, 184, 0.22);
  background: rgba(4, 8, 12, 0.8);
  padding: 4px;
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 10px), calc(100% - 10px) 100%, 0 100%);
}
#minimap { width: 100%; height: auto; display: block; opacity: 0.9; }
.mini-label { display: block; font-family: var(--mono); font-size: 6px; letter-spacing: 0.16em; color: var(--muted); padding: 3px 2px 0; }
.mini-north { position: absolute; top: 4px; right: 7px; font-family: var(--mono); font-size: 7px; color: var(--amber); }
.killfeed { display: flex; flex-direction: column; align-items: flex-end; gap: 3px; max-width: 100%; }
.kill-item { font-family: var(--mono); font-size: 8px; letter-spacing: 0.08em; color: var(--muted); background: rgba(5, 9, 14, 0.7); padding: 3px 6px; border-right: 1px solid var(--red); animation: kill-in 0.2s ease both; }
.kill-item b { color: var(--red); font-weight: 500; }
.kill-item.head b { color: var(--amber); }
@keyframes kill-in { from { opacity: 0; transform: translateX(8px); } }

.hud-bottom {
  position: absolute;
  left: calc(16px + var(--safe-left));
  right: calc(16px + var(--safe-right));
  bottom: calc(14px + var(--safe-bottom));
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 16px;
}
.hud-left { display: flex; flex-direction: column; gap: 8px; }
.weapon-hud {
  width: 260px;
  padding: 9px 12px 7px;
  background: linear-gradient(100deg, rgba(6, 11, 16, 0.88), rgba(6, 11, 16, 0.35));
  border-left: 2px solid var(--cyan);
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 12px), calc(100% - 12px) 100%, 0 100%);
}
.weapon-title { display: flex; align-items: baseline; gap: 8px; }
.weapon-title span { font-family: var(--mono); font-size: 7px; letter-spacing: 0.14em; color: var(--cyan); border: 1px solid rgba(56, 189, 248, 0.25); padding: 1px 4px; }
.weapon-title strong { font-family: var(--display); font-size: 14px; letter-spacing: 0.1em; font-weight: 600; }
.ammo-line { display: flex; align-items: baseline; gap: 5px; margin-top: 1px; }
.ammo-line b { font-family: var(--display); font-size: 30px; line-height: 1; letter-spacing: 0.03em; color: var(--text); }
.ammo-line span { font-family: var(--mono); font-size: 10px; color: var(--dim); }
.ammo-line em { margin-left: auto; font-style: normal; font-family: var(--mono); font-size: 7px; letter-spacing: 0.12em; color: var(--amber); }
.ammo-line b.low { color: var(--red); animation: blink 0.8s infinite; }
.reload-track { height: 2px; background: rgba(148, 163, 184, 0.14); margin-top: 4px; overflow: hidden; }
.reload-track i { display: block; height: 100%; width: 0; background: var(--cyan); }
.key-hint { font-family: var(--mono); font-size: 6.5px; letter-spacing: 0.08em; color: var(--dim); margin-top: 5px; white-space: nowrap; }
.key-hint kbd { font-family: var(--mono); font-size: 6.5px; padding: 0 2px; border: 1px solid rgba(148, 163, 184, 0.3); color: var(--muted); }
.equipment { display: flex; gap: 5px; }
.equip { display: flex; align-items: center; gap: 6px; padding: 5px 9px; background: rgba(6, 11, 16, 0.8); border: 1px solid var(--line); min-width: 72px; }
.equip-icon { font-size: 12px; color: var(--amber); }
.equip div { display: flex; flex-direction: column; line-height: 1; }
.equip b { font-family: var(--display); font-size: 11px; letter-spacing: 0.08em; font-weight: 600; }
.equip small { font-family: var(--mono); font-size: 5.5px; letter-spacing: 0.14em; color: var(--dim); margin-top: 2px; }
.pause-btn {
  position: absolute;
  top: calc(14px + var(--safe-top));
  right: calc(14px + var(--safe-right));
  width: 36px;
  height: 36px;
  background: rgba(6, 11, 16, 0.8);
  border: 1px solid var(--line);
  color: var(--muted);
  font-size: 10px;
  letter-spacing: 1px;
  cursor: pointer;
  pointer-events: auto;
  z-index: 4;
}
.pause-btn:hover { color: var(--text); border-color: var(--line-bright); }

.touch-only { display: none; }
body.touch .touch-only { display: flex; }
body.touch .key-hint { display: none; }
body.touch .equipment { display: none; }
body.touch .weapon-hud { width: 210px; padding: 7px 10px 6px; }
body.touch .ammo-line b { font-size: 25px; }
.hud-actions {
  position: relative;
  display: grid;
  grid-template-columns: repeat(3, 52px);
  grid-template-rows: repeat(2, 52px);
  gap: 7px;
  align-items: end;
  pointer-events: auto;
}
.act-btn {
  width: 52px;
  height: 52px;
  border-radius: 50%;
  border: 1px solid rgba(148, 163, 184, 0.3);
  background: rgba(6, 11, 16, 0.7);
  color: var(--muted);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0;
  backdrop-filter: blur(6px);
  pointer-events: auto;
  touch-action: none;
  transition: 0.08s;
}
.act-btn span { font-size: 18px; line-height: 1; color: var(--text); }
.act-btn small { font-family: var(--mono); font-size: 5px; letter-spacing: 0.1em; color: var(--dim); margin-top: 2px; }
.act-btn.primary { border-color: rgba(167, 139, 250, 0.5); background: rgba(88, 60, 160, 0.22); }
.act-btn.primary span { color: #c4b5fd; }
.act-btn:active { transform: scale(0.92); background: rgba(240, 162, 60, 0.2); }
.act-btn.cooling { opacity: 0.45; }
.act-btn .badge { position: absolute; top: -3px; right: -3px; min-width: 16px; height: 16px; border-radius: 8px; background: var(--amber); color: #170d03; font-family: var(--mono); font-size: 8px; display: grid; place-items: center; font-weight: 700; }
.act-btn { position: relative; }

.joystick {
  position: absolute;
  width: 116px;
  height: 116px;
  border-radius: 50%;
  border: 1px solid rgba(148, 163, 184, 0.22);
  background: radial-gradient(circle, rgba(148, 163, 184, 0.07), rgba(5, 9, 14, 0.18));
  transform: translate(-50%, -50%);
  opacity: 0;
  transition: opacity 0.12s;
  pointer-events: none;
  z-index: 3;
}
.joystick.active { opacity: 0.8; }
.joystick span { position: absolute; left: 50%; top: 50%; width: 6px; height: 6px; margin: -3px; border-radius: 50%; background: rgba(240, 162, 60, 0.5); }
.joystick i { position: absolute; left: 50%; top: 50%; width: 46px; height: 46px; margin: -23px; border-radius: 50%; border: 1px solid rgba(240, 162, 60, 0.45); background: rgba(240, 162, 60, 0.12); box-shadow: 0 0 24px rgba(240, 162, 60, 0.12); }
.joystick.aim { border-color: rgba(56, 189, 248, 0.24); }
.joystick.aim i { border-color: rgba(56, 189, 248, 0.5); background: rgba(56, 189, 248, 0.1); box-shadow: 0 0 24px rgba(56, 189, 248, 0.14); }
.joystick.aim span { background: rgba(56, 189, 248, 0.6); }
body:not(.touch) .joystick { display: none; }

.hud-toast {
  position: absolute;
  top: 18%;
  left: 50%;
  transform: translateX(-50%);
  padding: 8px 18px;
  background: rgba(6, 11, 16, 0.86);
  border-left: 2px solid var(--amber);
  border-right: 2px solid var(--amber);
  font-family: var(--display);
  font-size: 12px;
  letter-spacing: 0.18em;
  color: var(--text);
  opacity: 0;
  transition: opacity 0.25s, transform 0.25s;
  white-space: nowrap;
  max-width: 90vw;
  overflow: hidden;
  text-overflow: ellipsis;
}
.hud-toast.show { opacity: 1; transform: translateX(-50%) translateY(-3px); }
.hud-toast.good { border-color: var(--green); color: #bbf7d0; }
.hud-toast.bad { border-color: var(--red); color: #fecaca; }
.hud-tip {
  position: absolute;
  bottom: calc(104px + var(--safe-bottom));
  left: 50%;
  transform: translateX(-50%);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.1em;
  color: rgba(203, 213, 225, 0.7);
  background: rgba(5, 9, 14, 0.55);
  padding: 5px 10px;
  border: 1px solid rgba(148, 163, 184, 0.14);
  opacity: 0;
  transition: opacity 0.3s;
  white-space: nowrap;
}
.hud-tip.show { opacity: 1; }
.damage-flash {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: radial-gradient(ellipse at center, transparent 42%, rgba(220, 38, 38, 0.55) 100%);
  opacity: 0;
  transition: opacity 0.22s;
}
.low-health {
  position: absolute;
  inset: 0;
  pointer-events: none;
  box-shadow: inset 0 0 120px rgba(220, 38, 38, 0.28);
  opacity: 0;
  transition: opacity 0.4s;
}
.low-health.active { opacity: 1; animation: low-pulse 1.4s ease-in-out infinite; }
@keyframes low-pulse { 50% { opacity: 0.4; } }

/* --------------------------------------------------------------- overlay */
.overlay {
  position: fixed;
  inset: 0;
  z-index: 30;
  display: grid;
  place-items: center;
  padding: calc(16px + var(--safe-top)) calc(16px + var(--safe-right)) calc(16px + var(--safe-bottom)) calc(16px + var(--safe-left));
  background: radial-gradient(ellipse at center, rgba(5, 9, 14, 0.78), rgba(2, 4, 7, 0.94));
  backdrop-filter: blur(8px);
  animation: fade-in 0.2s ease both;
}
@keyframes fade-in { from { opacity: 0; } }
.panel {
  width: min(1120px, 96vw);
  max-height: min(860px, 92vh);
  display: flex;
  flex-direction: column;
  background: linear-gradient(165deg, rgba(12, 19, 28, 0.98), rgba(5, 9, 14, 0.98));
  border: 1px solid rgba(148, 163, 184, 0.24);
  box-shadow: 0 40px 120px rgba(0, 0, 0, 0.7), inset 0 1px 0 rgba(255, 255, 255, 0.04);
  position: relative;
  animation: panel-in 0.28s cubic-bezier(0.2, 0.8, 0.2, 1) both;
}
@keyframes panel-in { from { opacity: 0; transform: translateY(12px) scale(0.99); } }
.panel::before, .panel::after { content: ""; position: absolute; width: 22px; height: 22px; border: 1px solid var(--amber); opacity: 0.55; pointer-events: none; }
.panel::before { left: -1px; top: -1px; border-right: 0; border-bottom: 0; }
.panel::after { right: -1px; bottom: -1px; border-left: 0; border-top: 0; }
.panel-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 20px;
  padding: 20px 24px 14px;
  border-bottom: 1px solid var(--line);
  flex: 0 0 auto;
}
.panel-kicker { font-family: var(--mono); font-size: 8px; letter-spacing: 0.24em; color: var(--amber); }
.panel-head h2 { font-family: var(--display); font-size: clamp(24px, 3vw, 38px); letter-spacing: 0.05em; margin: 3px 0 0; line-height: 0.95; }
.panel-close { flex: 0 0 auto; }
.panel-body { padding: 18px 24px 22px; overflow: auto; flex: 1 1 auto; scrollbar-width: thin; scrollbar-color: rgba(148,163,184,.3) transparent; }
.panel-foot { display: flex; gap: 10px; justify-content: flex-end; flex-wrap: wrap; padding: 12px 24px calc(16px + var(--safe-bottom)); border-top: 1px solid var(--line); flex: 0 0 auto; }
.panel-foot:empty { display: none; }
.panel-body::-webkit-scrollbar { width: 6px; }
.panel-body::-webkit-scrollbar-thumb { background: rgba(148, 163, 184, 0.25); }

.ops-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; }
.op-card {
  position: relative;
  text-align: left;
  padding: 14px;
  border: 1px solid var(--line);
  background: rgba(8, 13, 19, 0.72);
  cursor: pointer;
  transition: 0.18s;
  overflow: hidden;
  color: var(--text);
}
.op-card:hover:not(.locked) { border-color: rgba(240, 162, 60, 0.5); background: rgba(240, 162, 60, 0.06); transform: translateY(-1px); }
.op-card.selected { border-color: var(--amber); background: rgba(240, 162, 60, 0.08); }
.op-card.locked { opacity: 0.42; cursor: not-allowed; filter: grayscale(0.6); }
.op-card .op-num { font-family: var(--mono); font-size: 9px; letter-spacing: 0.16em; color: var(--dim); }
.op-card h3 { font-family: var(--display); font-size: 20px; letter-spacing: 0.07em; margin: 2px 0 1px; }
.op-card .op-loc { font-family: var(--mono); font-size: 7px; letter-spacing: 0.12em; color: var(--muted); margin-bottom: 9px; }
.op-card .op-meta { display: flex; gap: 12px; font-family: var(--mono); font-size: 7px; letter-spacing: 0.08em; color: var(--dim); flex-wrap: wrap; }
.op-card .op-meta b { color: var(--amber); font-weight: 500; }
.op-card .op-badge { position: absolute; right: 10px; top: 10px; font-family: var(--mono); font-size: 7px; letter-spacing: 0.12em; padding: 3px 6px; border: 1px solid rgba(52, 211, 153, 0.3); color: var(--green); }
.op-card .op-badge.locked-badge { color: var(--dim); border-color: var(--line); }
.op-card .op-badge.new { color: var(--amber); border-color: rgba(240, 162, 60, 0.4); }
.op-card .op-clear { position: absolute; right: 10px; bottom: 10px; font-family: var(--mono); font-size: 6px; letter-spacing: 0.1em; color: rgba(52, 211, 153, 0.75); }
.op-card .op-preview { position: absolute; inset: 0; opacity: 0.08; background-size: cover; background-position: center; pointer-events: none; }

.skirmish-card {
  grid-column: 1 / -1;
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 14px;
  border: 1px dashed rgba(167, 139, 250, 0.35);
  background: linear-gradient(90deg, rgba(88, 60, 160, 0.12), transparent);
  cursor: pointer;
  text-align: left;
  color: var(--text);
}
.skirmish-card:hover { background: linear-gradient(90deg, rgba(88, 60, 160, 0.22), transparent); }
.skirmish-card .sk-icon { width: 46px; height: 46px; display: grid; place-items: center; border: 1px solid rgba(167, 139, 250, 0.4); color: #c4b5fd; font-size: 20px; flex: 0 0 auto; }
.skirmish-card h3 { font-family: var(--display); font-size: 18px; letter-spacing: 0.08em; margin: 0; }
.skirmish-card p { margin: 2px 0 0; font-size: 10px; color: var(--muted); }
.skirmish-card .sk-best { margin-left: auto; text-align: right; font-family: var(--mono); font-size: 7px; letter-spacing: 0.1em; color: var(--dim); }
.skirmish-card .sk-best b { display: block; font-family: var(--display); font-size: 20px; color: #c4b5fd; letter-spacing: 0.04em; }

.section-label { display: flex; align-items: center; gap: 10px; font-family: var(--mono); font-size: 8px; letter-spacing: 0.2em; color: var(--dim); margin: 18px 0 9px; }
.section-label:first-child { margin-top: 0; }
.section-label::after { content: ""; flex: 1; height: 1px; background: var(--line); }

.armory-layout { display: grid; grid-template-columns: minmax(0, 1.05fr) minmax(300px, 0.95fr); gap: 18px; align-items: start; }
.weapon-list { display: flex; flex-direction: column; gap: 7px; }
.weapon-row {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 12px;
  border: 1px solid var(--line);
  background: rgba(8, 13, 19, 0.7);
  cursor: pointer;
  text-align: left;
  color: var(--text);
  transition: 0.16s;
}
.weapon-row:hover { border-color: var(--line-bright); }
.weapon-row.selected { border-color: var(--amber); background: rgba(240, 162, 60, 0.07); }
.weapon-row.equipped { border-left: 2px solid var(--green); }
.weapon-row .w-icon { width: 40px; height: 40px; display: grid; place-items: center; border: 1px solid var(--line); color: var(--muted); font-size: 17px; flex: 0 0 auto; background: rgba(148, 163, 184, 0.04); }
.weapon-row .w-info { flex: 1; min-width: 0; }
.weapon-row .w-info strong { display: block; font-family: var(--display); font-size: 14px; letter-spacing: 0.08em; }
.weapon-row .w-info span { font-family: var(--mono); font-size: 7px; letter-spacing: 0.12em; color: var(--dim); }
.weapon-row .w-price { font-family: var(--mono); font-size: 9px; color: var(--amber); white-space: nowrap; }
.weapon-row .w-price.owned { color: var(--green); }
.weapon-row .w-price.locked { color: var(--dim); }
.weapon-detail { border: 1px solid var(--line); padding: 16px; background: rgba(8, 13, 19, 0.66); }
.weapon-detail h3 { font-family: var(--display); font-size: 26px; letter-spacing: 0.06em; margin: 0; }
.weapon-detail .wd-class { font-family: var(--mono); font-size: 8px; letter-spacing: 0.16em; color: var(--cyan); }
.weapon-detail p { font-size: 11px; line-height: 1.55; color: var(--muted); margin: 10px 0 14px; }
.stat-bars { display: flex; flex-direction: column; gap: 7px; margin-bottom: 16px; }
.stat-bar { display: grid; grid-template-columns: 60px 1fr 32px; align-items: center; gap: 8px; font-family: var(--mono); font-size: 7px; letter-spacing: 0.1em; color: var(--dim); }
.stat-bar .track { height: 5px; background: rgba(148, 163, 184, 0.12); overflow: hidden; }
.stat-bar .track i { display: block; height: 100%; background: linear-gradient(90deg, var(--cyan), var(--amber)); }
.stat-bar b { color: var(--muted); font-weight: 500; text-align: right; }
.detail-actions { display: flex; gap: 8px; flex-wrap: wrap; }
.btn-solid { padding: 10px 16px; background: var(--amber); color: #170e03; border: 0; font-family: var(--display); font-size: 12px; letter-spacing: 0.14em; cursor: pointer; }
.btn-solid:hover { filter: brightness(1.1); }
.btn-solid:disabled { background: rgba(148, 163, 184, 0.16); color: var(--dim); cursor: not-allowed; }
.btn-outline { padding: 10px 16px; background: transparent; border: 1px solid var(--line-bright); color: var(--muted); font-family: var(--display); font-size: 12px; letter-spacing: 0.14em; cursor: pointer; }
.btn-outline:hover { color: var(--text); border-color: var(--amber); }
.upgrade-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px; }
.upgrade {
  display: flex;
  gap: 10px;
  align-items: flex-start;
  padding: 10px;
  border: 1px solid var(--line);
  background: rgba(8, 13, 19, 0.6);
  cursor: pointer;
  text-align: left;
  color: var(--text);
  transition: 0.16s;
}
.upgrade:hover:not(.owned) { border-color: rgba(240, 162, 60, 0.45); }
.upgrade.owned { border-color: rgba(52, 211, 153, 0.3); background: rgba(52, 211, 153, 0.05); cursor: default; }
.upgrade .u-icon { width: 30px; height: 30px; flex: 0 0 auto; display: grid; place-items: center; border: 1px solid var(--line); color: var(--amber); font-size: 13px; }
.upgrade.owned .u-icon { color: var(--green); border-color: rgba(52, 211, 153, 0.35); }
.upgrade .u-info strong { display: block; font-family: var(--display); font-size: 11px; letter-spacing: 0.08em; }
.upgrade .u-info span { display: block; font-size: 9px; color: var(--muted); line-height: 1.35; margin-top: 2px; }
.upgrade .u-price { margin-left: auto; font-family: var(--mono); font-size: 8px; color: var(--amber); white-space: nowrap; }
.upgrade.owned .u-price { color: var(--green); }
.loadout-bar { display: flex; align-items: center; gap: 10px; padding: 10px 12px; border: 1px solid var(--line); background: rgba(8, 13, 19, 0.7); margin-bottom: 14px; font-family: var(--mono); font-size: 8px; letter-spacing: 0.1em; color: var(--muted); flex-wrap: wrap; }
.loadout-bar b { color: var(--amber); font-weight: 500; }
.loadout-bar .credits { margin-left: auto; color: var(--amber-bright); font-size: 10px; }

.manual-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; }
.manual-card { border: 1px solid var(--line); padding: 14px; background: rgba(8, 13, 19, 0.62); }
.manual-card h3 { font-family: var(--display); font-size: 15px; letter-spacing: 0.1em; margin: 0 0 8px; color: var(--amber); }
.manual-card p { font-size: 10.5px; line-height: 1.55; color: var(--muted); margin: 0 0 8px; }
.manual-card p:last-child { margin-bottom: 0; }
.key-table { display: grid; grid-template-columns: auto 1fr; gap: 5px 12px; font-size: 10px; color: var(--muted); }
.key-table kbd { font-family: var(--mono); font-size: 8px; color: var(--text); border: 1px solid var(--line-bright); padding: 2px 5px; text-align: center; }
.enemy-row { display: flex; gap: 10px; align-items: flex-start; padding: 7px 0; border-bottom: 1px solid rgba(148, 163, 184, 0.1); }
.enemy-row:last-child { border-bottom: 0; }
.enemy-dot { width: 9px; height: 9px; border-radius: 50%; margin-top: 4px; flex: 0 0 auto; box-shadow: 0 0 8px currentColor; }
.enemy-row strong { font-family: var(--display); font-size: 11px; letter-spacing: 0.1em; }
.enemy-row span { display: block; font-size: 9px; color: var(--muted); line-height: 1.4; }

.settings-list { display: flex; flex-direction: column; gap: 2px; max-width: 620px; }
.setting-row { display: flex; align-items: center; justify-content: space-between; gap: 20px; padding: 14px 2px; border-bottom: 1px solid var(--line); }
.setting-row .s-info strong { display: block; font-family: var(--display); font-size: 12px; letter-spacing: 0.1em; }
.setting-row .s-info span { font-size: 9px; color: var(--muted); }
.setting-row input[type="range"] { width: 160px; accent-color: var(--amber); }
.toggle { position: relative; width: 48px; height: 24px; border: 1px solid var(--line-bright); background: rgba(148, 163, 184, 0.08); cursor: pointer; padding: 0; }
.toggle::after { content: ""; position: absolute; left: 3px; top: 3px; width: 16px; height: 16px; background: var(--dim); transition: 0.18s; }
.toggle.on { border-color: rgba(52, 211, 153, 0.5); background: rgba(52, 211, 153, 0.1); }
.toggle.on::after { left: 27px; background: var(--green); box-shadow: 0 0 10px rgba(52, 211, 153, 0.5); }
.danger-btn { padding: 9px 14px; border: 1px solid rgba(248, 113, 113, 0.4); background: rgba(248, 113, 113, 0.06); color: #fca5a5; font-family: var(--display); font-size: 11px; letter-spacing: 0.12em; cursor: pointer; }
.danger-btn:hover { background: rgba(248, 113, 113, 0.14); }

.briefing-grid { display: grid; grid-template-columns: 1.3fr 0.7fr; gap: 18px; }
.briefing-text p { font-size: 12px; line-height: 1.65; color: #b6c2cf; margin: 0 0 12px; }
.briefing-text .intel-line { font-family: var(--mono); font-size: 8px; letter-spacing: 0.12em; color: var(--amber); }
.briefing-facts { border: 1px solid var(--line); padding: 14px; background: rgba(8, 13, 19, 0.6); }
.fact { display: flex; justify-content: space-between; gap: 10px; padding: 6px 0; border-bottom: 1px solid rgba(148, 163, 184, 0.1); font-family: var(--mono); font-size: 8px; letter-spacing: 0.1em; color: var(--dim); }
.fact:last-child { border-bottom: 0; }
.fact b { color: var(--text); font-weight: 500; text-align: right; }
.tip-box { margin-top: 12px; padding: 10px 12px; border-left: 2px solid var(--cyan); background: rgba(56, 189, 248, 0.06); font-size: 10px; line-height: 1.5; color: #bae6fd; }

.results { text-align: center; padding: 6px 0 2px; }
.results .result-kicker { font-family: var(--mono); font-size: 9px; letter-spacing: 0.3em; color: var(--green); }
.results h2 { font-family: var(--display); font-size: clamp(36px, 5vw, 64px); letter-spacing: 0.06em; margin: 4px 0 0; line-height: 0.9; }
.results h2.failed { color: var(--red); }
.results .result-sub { font-family: var(--mono); font-size: 9px; letter-spacing: 0.14em; color: var(--muted); margin-top: 8px; }
.result-stats { display: grid; grid-template-columns: repeat(4, 1fr); gap: 1px; margin: 22px auto 14px; max-width: 720px; background: var(--line); border: 1px solid var(--line); }
.result-stats div { background: rgba(8, 13, 19, 0.9); padding: 12px 8px; }
.result-stats span { display: block; font-family: var(--mono); font-size: 7px; letter-spacing: 0.14em; color: var(--dim); margin-bottom: 4px; }
.result-stats b { font-family: var(--display); font-size: 24px; letter-spacing: 0.04em; }
.result-stats b.gold { color: var(--amber); }
.result-stats b.green { color: var(--green); }
.result-rewards { display: flex; justify-content: center; gap: 20px; flex-wrap: wrap; font-family: var(--mono); font-size: 9px; letter-spacing: 0.12em; color: var(--muted); margin: 12px 0 4px; }
.result-rewards b { color: var(--amber); }
.result-rank { display: inline-flex; align-items: center; gap: 10px; margin-top: 14px; padding: 8px 18px; border: 1px solid rgba(240, 162, 60, 0.35); background: rgba(240, 162, 60, 0.06); font-family: var(--display); font-size: 12px; letter-spacing: 0.18em; color: var(--amber-bright); }
.result-rank b { font-size: 26px; line-height: 1; }

.deploy {
  position: fixed;
  inset: 0;
  z-index: 35;
  display: grid;
  place-items: center;
  background: #030507;
  overflow: hidden;
}
.deploy-scan {
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(0deg, rgba(56, 189, 248, 0.06) 0 1px, transparent 1px 4px);
  animation: scan-move 0.8s linear infinite;
}
@keyframes scan-move { to { background-position: 0 16px; } }
.deploy-inner { text-align: center; position: relative; z-index: 2; animation: deploy-in 0.3s ease both; }
@keyframes deploy-in { from { opacity: 0; transform: scale(1.03); } }
.deploy-kicker { font-family: var(--mono); font-size: 9px; letter-spacing: 0.4em; color: var(--amber); }
.deploy-inner h2 { font-family: var(--display); font-size: clamp(40px, 7vw, 90px); letter-spacing: 0.08em; margin: 6px 0 2px; line-height: 0.9; }
.deploy-inner p { font-family: var(--mono); font-size: 9px; letter-spacing: 0.2em; color: var(--muted); margin: 0 0 26px; }
.deploy-bar { width: min(360px, 70vw); height: 2px; background: rgba(148, 163, 184, 0.18); margin: 0 auto 10px; }
.deploy-bar i { display: block; height: 100%; width: 0; background: var(--amber); box-shadow: 0 0 12px var(--amber); }
.deploy-status { font-family: var(--mono); font-size: 7px; letter-spacing: 0.22em; color: var(--dim); }

.rotate-hint {
  position: fixed;
  top: calc(10px + var(--safe-top));
  left: 50%;
  transform: translateX(-50%);
  z-index: 45;
  background: rgba(6, 11, 16, 0.9);
  border: 1px solid rgba(240, 162, 60, 0.3);
  padding: 6px 12px;
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.12em;
  color: var(--amber);
  white-space: nowrap;
  pointer-events: none;
}

