import { openPage } from './cdp.mjs';

const page = await openPage('http://localhost:8123/index.html');
await page.wait(2500);
await page.evaluate('localStorage.clear(); location.reload();');
await page.wait(2500);
console.log('SW REGS', await page.evaluate(`navigator.serviceWorker.getRegistrations().then(r => r.length)`, true));
console.log('SW READY', await page.evaluate(`navigator.serviceWorker.ready.then(r => r.active ? r.active.state : 'none')`, true));

// Fresh save: skirmish should be locked in campaign panel
await page.evaluate(`game.ui.openPanel('campaign')`);
await page.wait(400);
console.log('LOCKED CARD', await page.evaluate(`(() => { const b=document.querySelector('.skirmish-card'); return {locked:b.classList.contains('locked'), disabled:b.disabled, text:b.textContent.replace(/\\s+/g,' ').trim().slice(0,90)}; })()`));
await page.evaluate(`game.ui.openPanel('armory')`);
await page.wait(300);
await page.evaluate(`(() => { game.save.credits=99999; game.persist(); game.ui.openPanel('armory'); })()`);
await page.wait(400);
console.log('UPGRADE BTN', await page.evaluate(`document.querySelectorAll('[data-act=buyUpgrade]').length`));
await page.evaluate(`document.querySelector('[data-act=buyUpgrade]').click()`);
await page.wait(400);
console.log('AFTER UPGRADE', await page.evaluate(`({panel:game.ui.panelKind, ups:game.save.upgrades, credits:game.save.credits})`));
await page.evaluate(`game.buyWeapon('sentinel'); game.startMission(0)`);
await page.wait(1200);
console.log('LOADOUT', await page.evaluate(`(() => { const w=game.player.weapons[0]; return {name:w.name, mag:w.mag, reserve:w.reserve, maxArmor:game.player.maxArmor, grenades:game.player.grenades}; })()`));
await page.evaluate('game.abortMission()');
await page.wait(500);

// Complete campaign quickly
for (let i = 0; i < 6; i++) {
  await page.evaluate(`game.startMission(${i})`);
  await page.wait(900);
  await page.evaluate(`(() => { const g=game; for (const e of g.enemies) if(!e.dead) g.damageEnemy(e, 9999, 0, true, e.x, e.y, true); })()`);
  await page.wait(300);
  await page.evaluate(`(() => { const g=game; g.player.x=g.map.extraction.x; g.player.y=g.map.extraction.y; })()`);
  await page.wait(500);
  await page.evaluate('game.continueAfterResults()');
  await page.wait(800);
}
await page.evaluate('game.returnToMenu()');
await page.wait(400);
await page.evaluate(`game.ui.openPanel('campaign')`);
await page.wait(400);
console.log('UNLOCKED CARD', await page.evaluate(`(() => { const b=document.querySelector('.skirmish-card'); return {locked:b.classList.contains('locked'), disabled:b.disabled, text:b.textContent.replace(/\\s+/g,' ').trim().slice(0,80)}; })()`));
await page.evaluate(`document.querySelector('.skirmish-card').click()`);
await page.wait(400);
console.log('SKIRMISH BRIEF', await page.evaluate(`({panel:game.ui.panelKind, hasDeploy:!!document.querySelector('[data-act=deploySkirmish]')})`));
await page.screenshot('/tmp/opencode/shot-61-skirmish-brief.jpg', 55);
await page.evaluate(`document.querySelector('[data-act=deploySkirmish]').click()`);
await page.wait(1200);
console.log('SKIRMISH DEPLOYED', await page.evaluate(`({state:game.state, skirmish:game.skirmish, wave:game.wave})`));
await page.evaluate('game.returnToMenu()');
await page.wait(400);
console.log('MENU CARD', await page.evaluate(`({tag:document.getElementById('card-tag').textContent, name:document.getElementById('card-name').textContent, kicker:document.getElementById('play-kicker').textContent})`));
await page.screenshot('/tmp/opencode/shot-62-menu-allclear.jpg', 55);
console.log('CONTROLLER', await page.evaluate(`({padSupported:!!navigator.getGamepads, padIndexes:Array.from(navigator.getGamepads()).map(p=>!!p)})`));
console.log('ERRORS', JSON.stringify(page.drain().filter((e) => e.level === 'exception' || e.level === 'error')));
await page.close();

