import { openPage } from './cdp.mjs';

const page = await openPage('http://localhost:8123/index.html');
await page.wait(2500);
await page.evaluate('localStorage.clear(); location.reload();');
await page.wait(3000);
await page.evaluate('location.reload()');
await page.wait(3000);
console.log('CONTROLLED', await page.evaluate(`!!navigator.serviceWorker.controller`));

// Gamepad simulation
await page.evaluate(`(() => {
  const fake = {
    connected: true, index: 0, id: 'test-pad', mapping: 'standard',
    axes: [0, 0, 0.9, 0.1, 0, 0, 0, 0],
    buttons: Array.from({ length: 17 }, () => ({ pressed: false, value: 0 })),
  };
  navigator.getGamepads = () => [fake, null, null, null];
  window.__fakePad = fake;
  game.startMission(0);
})()`);
await page.wait(1500);
console.log('PAD STATE', await page.evaluate(`({state:game.state, pad:JSON.parse(JSON.stringify(game.input.pad))})`));
await page.wait(1200);
console.log('PAD FIRED', await page.evaluate(`({shots:game.run.shots, fire:game.input.pad.fire, angle:game.player.angle.toFixed(2)})`));
await page.evaluate(`(() => { __fakePad.buttons[2] = {pressed:true, value:1}; })()`);
await page.wait(200);
await page.evaluate(`(() => { __fakePad.buttons[2] = {pressed:false, value:0}; })()`);
await page.wait(300);
console.log('PAD RELOAD', await page.evaluate(`({reloading:game.player.weapons[0].reloading, mag:game.player.weapons[0].mag})`));
await page.evaluate(`(() => { __fakePad.buttons[9] = {pressed:true, value:1}; })()`);
await page.wait(300);
await page.evaluate(`(() => { __fakePad.buttons[9] = {pressed:false, value:0}; })()`);
await page.wait(300);
console.log('PAD PAUSE', await page.evaluate(`({state:game.state, panel:game.ui.panelKind})`));
await page.evaluate('game.returnToMenu()');
await page.wait(300);
await page.evaluate('delete window.__fakePad');

// Offline check
await page.send('Network.enable');
await page.send('Network.emulateNetworkConditions', { offline: true, latency: 0, downloadThroughput: 0, uploadThroughput: 0 });
await page.evaluate('location.reload()');
await page.wait(3000);
console.log('OFFLINE BOOT', await page.evaluate(`({hasGame:!!window.game, state:window.game?.state, menu:!document.getElementById('menu').classList.contains('hidden'), css:getComputedStyle(document.body).backgroundColor})`));
console.log('OFFLINE ERRORS', JSON.stringify(page.drain().filter((e) => e.level === 'exception' || e.level === 'error')));
await page.send('Network.emulateNetworkConditions', { offline: false, latency: 0, downloadThroughput: -1, uploadThroughput: -1 });
await page.close();

