175:         ctx.beginPath();
176:         ctx.arc(blip.x, blip.y, 4, 0, Math.PI * 2);
177:         ctx.fill();
178:       }
179:     }
180:     ctx.fillStyle = 'rgba(74,222,128,0.55)';
181:     ctx.beginPath();
182:     ctx.arc(g.menuMap.extraction.x, g.menuMap.extraction.y, 5, 0, Math.PI * 2);
183:     ctx.fill();
184:     ctx.restore();
185:     // Screen-space atmosphere.
186:     ctx.save();
187:     const grad = ctx.createLinearGradient(0, 0, this.view.w, this.view.h);
188:     grad.addColorStop(0, 'rgba(4,7,11,0.93)');
189:     grad.addColorStop(0.42, 'rgba(4,7,11,0.62)');
190:     grad.addColorStop(0.72, 'rgba(4,7,11,0.3)');
191:     grad.addColorStop(1, 'rgba(4,7,11,0.72)');
192:     ctx.fillStyle = grad;
193:     ctx.fillRect(0, 0, this.view.w, this.view.h);
194:     const glow = ctx.createRadialGradient(this.view.w * 0.72, this.view.h * 0.36, 0, this.view.w * 0.72, this.view.h * 0.36, this.view.w * 0.5);
195:     glow.addColorStop(0, 'rgba(240,162,60,0.06)');
196:     glow.addColorStop(0.5, 'rgba(56,189,248,0.03)');
197:     glow.addColorStop(1, 'rgba(0,0,0,0)');
198:     ctx.fillStyle = glow;
199:     ctx.fillRect(0, 0, this.view.w, this.view.h);
200:     // Drifting embers / dust.
201:     ctx.globalCompositeOperation = 'lighter';
202:     for (let i = 0; i < 34; i++) {
203:       const seed = i * 91.7;
204:       const x = (Math.sin(seed + t * (0.03 + (i % 5) * 0.012)) * 0.5 + 0.5) * this.view.w;
205:       const y = ((seed * 1.7 + t * (6 + (i % 7) * 2.5)) % (this.view.h + 80)) - 40;
206:       const alpha = 0.05 + (i % 4) * 0.025;
207:       ctx.fillStyle = i % 5 === 0 ? `rgba(240,162,60,${alpha})` : `rgba(125,211,252,${alpha})`;
208:       ctx.fillRect(x, y, 1.4, 1.4);
209:     }
210:     ctx.globalCompositeOperation = 'source-over';
211:     ctx.restore();
212:   }
