214:   drawCardRadar() {
215:     const g = this.game;
216:     const ctx = this.cardCtx;
217:     const c = this.card;
218:     if (!ctx || !c || g.state !== 'menu' || !g.menuMap) return;
219:     const w = c.width;
220:     const h = c.height;
221:     const mm = g.menuMap.minimap;
222:     if (mm) {
223:       const scale = Math.max(w / mm.width, h / mm.height);
224:       const dw = mm.width * scale;
225:       const dh = mm.height * scale;
226:       ctx.clearRect(0, 0, w, h);
227:       ctx.drawImage(mm, (w - dw) / 2, (h - dh) / 2, dw, dh);
228:     }
229:     ctx.fillStyle = 'rgba(3,9,14,0.56)';
230:     ctx.fillRect(0, 0, w, h);
231:     // Grid + crosshair.
232:     ctx.strokeStyle = 'rgba(125,211,252,0.08)';
233:     ctx.lineWidth = 1;
234:     for (let x = 0; x < w; x += 32) {
235:       ctx.beginPath();
236:       ctx.moveTo(x, 0);
237:       ctx.lineTo(x, h);
238:       ctx.stroke();
239:     }
240:     for (let y = 0; y < h; y += 32) {
241:       ctx.beginPath();
242:       ctx.moveTo(0, y);
243:       ctx.lineTo(w, y);
244:       ctx.stroke();
245:     }
246:     ctx.strokeStyle = 'rgba(240,162,60,0.22)';
247:     ctx.beginPath();
248:     ctx.arc(w / 2, h / 2, Math.min(w, h) * 0.31, 0, Math.PI * 2);
249:     ctx.stroke();
250:     const cx = w * 0.56;
251:     const cy = h * 0.48;
252:     const sweep = g.time * 1.15;
253:     ctx.save();
254:     ctx.translate(cx, cy);
255:     ctx.rotate(sweep);
256:     const rg = ctx.createLinearGradient(0, 0, Math.max(w, h) * 0.6, 0);
257:     rg.addColorStop(0, 'rgba(125,211,252,0.22)');
258:     rg.addColorStop(1, 'rgba(125,211,252,0)');
259:     ctx.fillStyle = rg;
260:     ctx.beginPath();
261:     ctx.moveTo(0, 0);
262:     ctx.arc(0, 0, Math.max(w, h) * 0.6, -0.5, 0);
263:     ctx.closePath();
264:     ctx.fill();
265:     ctx.strokeStyle = 'rgba(125,211,252,0.5)';
266:     ctx.beginPath();
267:     ctx.moveTo(0, 0);
268:     ctx.lineTo(Math.max(w, h) * 0.6, 0);
269:     ctx.stroke();
270:     ctx.restore();
271:     const toRadar = (wx, wy) => {
272:       const scale = Math.max(w / WORLD_W, h / WORLD_H);
273:       const dw = WORLD_W * scale;
274:       const dh = WORLD_H * scale;
275:       const ox = (w - dw) / 2;
276:       const oy = (h - dh) / 2;
277:       return { x: ox + wx * scale, y: oy + wy * scale };
278:     };
279:     const blips = [
280:       ...g.menuMap.intel.map((i) => ({ ...i, color: '#fbbf24' })),
281:       ...g.menuMap.enemySpawns.map((s) => ({ ...s, color: '#f87171' })),
282:       { ...g.menuMap.extraction, color: '#4ade80' },
283:     ];
284:     for (const b of blips) {
285:       const p = toRadar(b.x, b.y);
286:       const ang = Math.atan2(p.y - cy, p.x - cx);
287:       const diff = Math.abs(Math.atan2(Math.sin(ang - sweep), Math.cos(ang - sweep)));
288:       const a = Math.max(0.2, 1 - diff / 1.5);
289:       ctx.globalAlpha = a;
290:       ctx.fillStyle = b.color;
291:       ctx.beginPath();
292:       ctx.arc(p.x, p.y, b.color === '#4ade80' ? 3 : 2, 0, Math.PI * 2);
293:       ctx.fill();
294:       ctx.globalAlpha = 1;
295:     }
296:     ctx.strokeStyle = 'rgba(240,162,60,0.5)';
297:     ctx.strokeRect(0.5, 0.5, w - 1, h - 1);
298:   }
