300:   // ------------------------------------------------------------------- game
301:   renderGame() {
302:     const g = this.game;
303:     const ctx = this.ctx;
304:     ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
305:     ctx.fillStyle = '#04060a';
306:     ctx.fillRect(0, 0, this.view.w, this.view.h);
307:     if (!g.map || !g.player) return;
308:     const cam = this.camera;
309:     ctx.save();
310:     ctx.translate(this.view.w / 2 + cam.sx, this.view.h / 2 + cam.sy);
311:     ctx.scale(cam.zoom, cam.zoom);
312:     ctx.translate(-cam.x, -cam.y);
313:     this.drawLayer(g.map.canvas, cam);
314:     this.drawLayer(g.decals, cam);
315:     this.drawExtraction();
316:     this.drawIntel();
317:     this.drawPickups();
318:     this.drawVisionCones();
319:     this.drawGrenades();
320:     for (const e of g.enemies) if (!e.dead && this.inView(e.x, e.y)) this.drawEnemy(e);
321:     if (!g.player.dead) this.drawPlayer();
322:     this.drawBullets();
323:     this.drawParticles();
324:     this.drawTexts();
325:     this.drawAimLine();
326:     ctx.restore();
327:     this.drawLighting();
328:     if (g.player.focusActive > 0) {
329:       ctx.fillStyle = 'rgba(125,211,252,0.035)';
330:       ctx.fillRect(0, 0, this.view.w, this.view.h);
331:     }
332:     this.drawObjectiveMarkers();
333:     this.drawCrosshair();
334:     this.drawMinimap();
335:   }
