337:   drawExtraction() {
338:     const g = this.game;
339:     const ex = g.map.extraction;
340:     const ctx = this.ctx;
341:     const t = g.time;
342:     const active = g.extractionActive;
343:     const pulse = 0.5 + Math.sin(t * 2.4) * 0.5;
344:     ctx.save();
345:     ctx.translate(ex.x, ex.y);
346:     if (active) {
347:       const grad = ctx.createRadialGradient(0, 0, 4, 0, 0, 90);
348:       grad.addColorStop(0, `rgba(52,211,153,${0.1 + pulse * 0.07})`);
349:       grad.addColorStop(1, 'rgba(52,211,153,0)');
350:       ctx.fillStyle = grad;
351:       ctx.beginPath();
352:       ctx.arc(0, 0, 90, 0, Math.PI * 2);
353:       ctx.fill();
354:     }
355:     ctx.strokeStyle = active ? `rgba(52,211,153,${0.55 + pulse * 0.3})` : 'rgba(100,116,139,0.18)';
356:     ctx.lineWidth = 2;
357:     ctx.setLineDash([10, 8]);
358:     ctx.lineDashOffset = active ? -t * 26 : 0;
359:     ctx.beginPath();
360:     ctx.arc(0, 0, 58, 0, Math.PI * 2);
361:     ctx.stroke();
362:     ctx.setLineDash([]);
363:     ctx.strokeStyle = active ? 'rgba(52,211,153,0.8)' : 'rgba(100,116,139,0.3)';
364:     ctx.lineWidth = 1.5;
365:     for (let i = 0; i < 4; i++) {
366:       const a = (Math.PI / 2) * i + (active ? t * 0.8 : 0);
367:       ctx.beginPath();
368:       ctx.moveTo(Math.cos(a) * 47, Math.sin(a) * 47);
369:       ctx.lineTo(Math.cos(a) * 66, Math.sin(a) * 66);
370:       ctx.stroke();
371:     }
372:     ctx.fillStyle = active ? `rgba(52,211,153,${0.55 + pulse * 0.35})` : 'rgba(100,116,139,0.35)';
373:     ctx.beginPath();
374:     ctx.arc(0, 0, active ? 4 + pulse * 2 : 3, 0, Math.PI * 2);
375:     ctx.fill();
376:     ctx.font = '700 9px "Bahnschrift", "Arial Narrow", sans-serif';
377:     ctx.textAlign = 'center';
378:     ctx.letterSpacing = '2px';
379:     ctx.fillStyle = active ? 'rgba(167,243,208,0.9)' : 'rgba(148,163,184,0.3)';
380:     ctx.fillText(active ? 'EXFIL' : 'EXFIL LOCKED', 0, -72);
381:     ctx.restore();
382:   }
