384:   drawIntel() {
385:     const g = this.game;
386:     const ctx = this.ctx;
387:     for (const item of g.map.intel) {
388:       if (item.taken || !this.inView(item.x, item.y, 80)) continue;
389:       const t = g.time + item.pulse;
390:       const bob = Math.sin(t * 2.2) * 2;
391:       const pulse = 0.5 + Math.sin(t * 3) * 0.5;
392:       ctx.save();
393:       ctx.translate(item.x, item.y);
394:       ctx.fillStyle = 'rgba(0,0,0,0.4)';
395:       ctx.beginPath();
396:       ctx.ellipse(0, 7, 10, 4, 0, 0, Math.PI * 2);
397:       ctx.fill();
398:       const grad = ctx.createRadialGradient(0, bob, 0, 0, bob, 34);
399:       grad.addColorStop(0, `rgba(251,191,36,${0.18 + pulse * 0.12})`);
400:       grad.addColorStop(1, 'rgba(251,191,36,0)');
401:       ctx.fillStyle = grad;
402:       ctx.beginPath();
403:       ctx.arc(0, bob, 34, 0, Math.PI * 2);
404:       ctx.fill();
405:       ctx.translate(0, bob);
406:       ctx.rotate(-0.18);
407:       ctx.fillStyle = '#1f2937';
408:       ctx.fillRect(-8, -6, 16, 11);
409:       ctx.fillStyle = '#fbbf24';
410:       ctx.fillRect(-7, -5, 14, 7);
411:       ctx.fillStyle = 'rgba(255,255,255,0.55)';
412:       ctx.fillRect(-6, -4, 5, 1.2);
413:       ctx.fillRect(-6, -2, 8, 1.2);
414:       ctx.strokeStyle = 'rgba(251,191,36,0.5)';
415:       ctx.lineWidth = 1;
416:       ctx.strokeRect(-8.5, -6.5, 17, 12);
417:       ctx.fillStyle = 'rgba(251,191,36,0.8)';
418:       ctx.font = '600 6px "Bahnschrift", sans-serif';
419:       ctx.textAlign = 'center';
420:       ctx.fillText('INTEL', 0, -13);
421:       ctx.restore();
422:     }
423:   }
