425:   drawPickups() {
426:     const g = this.game;
427:     const ctx = this.ctx;
428:     for (const item of g.pickups) {
429:       if (!this.inView(item.x, item.y, 40)) continue;
430:       const bob = Math.sin(item.bob) * 2;
431:       const fade = item.life < 5 ? 0.4 + Math.sin(item.life * 12) * 0.25 : 1;
432:       ctx.save();
433:       ctx.globalAlpha = fade;
434:       ctx.translate(item.x, item.y);
435:       ctx.fillStyle = 'rgba(0,0,0,0.4)';
436:       ctx.beginPath();
437:       ctx.ellipse(0, 7, 9, 4, 0, 0, Math.PI * 2);
438:       ctx.fill();
439:       ctx.translate(0, bob);
440:       if (item.type === 'ammo') {
441:         ctx.fillStyle = '#0f1a24';
442:         ctx.fillRect(-7, -6, 14, 11);
443:         ctx.strokeStyle = 'rgba(125,211,252,0.55)';
444:         ctx.strokeRect(-7, -6, 14, 11);
445:         ctx.fillStyle = '#e0a94a';
446:         for (let i = 0; i < 3; i++) ctx.fillRect(-4 + i * 4, -3, 2, 6);
447:       } else if (item.type === 'med') {
448:         ctx.fillStyle = '#0f1a24';
449:         ctx.fillRect(-7, -6, 14, 11);
450:         ctx.strokeStyle = 'rgba(74,222,128,0.55)';
451:         ctx.strokeRect(-7, -6, 14, 11);
452:         ctx.fillStyle = '#4ade80';
453:         ctx.fillRect(-1.5, -4, 3, 8);
454:         ctx.fillRect(-4, -1.5, 8, 3);
455:       } else {
456:         ctx.fillStyle = '#0f1a24';
457:         ctx.beginPath();
458:         ctx.moveTo(0, -7);
459:         ctx.lineTo(7, -4);
460:         ctx.lineTo(6, 3);
461:         ctx.lineTo(0, 7);
462:         ctx.lineTo(-6, 3);
463:         ctx.lineTo(-7, -4);
464:         ctx.closePath();
465:         ctx.fill();
466:         ctx.strokeStyle = 'rgba(56,189,248,0.6)';
467:         ctx.stroke();
468:         ctx.fillStyle = '#38bdf8';
469:         ctx.fillRect(-1, -3, 2, 6);
470:         ctx.fillRect(-3, -1, 6, 2);
471:       }
472:       ctx.restore();
473:     }
474:   }
