476:   drawVisionCones() {
477:     const g = this.game;
478:     const ctx = this.ctx;
479:     ctx.save();
480:     for (const e of g.enemies) {
481:       if (e.dead || e.alert < 0.45 || e.state === 'patrol') continue;
482:       if (!this.inView(e.x, e.y, e.def.vision)) continue;
483:       const range = Math.min(e.def.vision, 820);
484:       const steps = 15;
485:       const points = [];
486:       for (let i = 0; i <= steps; i++) {
487:         const a = e.angle - e.def.cone + (e.def.cone * 2 * i) / steps;
488:         const ex = e.x + Math.cos(a) * range;
489:         const ey = e.y + Math.sin(a) * range;
490:         const hit = g.map.raycast(e.x, e.y, ex, ey, range);
491:         points.push(hit ? { x: hit.x, y: hit.y } : { x: ex, y: ey });
492:       }
493:       const grad = ctx.createRadialGradient(e.x, e.y, 10, e.x, e.y, range);
494:       const alpha = e.canSee ? 0.09 : 0.045;
495:       grad.addColorStop(0, hexA(e.def.color, alpha));
496:       grad.addColorStop(0.7, hexA(e.def.color, alpha * 0.4));
497:       grad.addColorStop(1, hexA(e.def.color, 0));
498:       ctx.fillStyle = grad;
499:       ctx.beginPath();
500:       ctx.moveTo(e.x, e.y);
501:       for (const p of points) ctx.lineTo(p.x, p.y);
502:       ctx.closePath();
503:       ctx.fill();
504:     }
505:     ctx.restore();
506:   }
