508:   drawGrenades() {
509:     const g = this.game;
510:     const ctx = this.ctx;
511:     for (const gr of g.grenades) {
512:       const progress = 1 - gr.timer / gr.max;
513:       const z = Math.sin(clamp(progress, 0, 1) * Math.PI) * 13;
514:       ctx.save();
515:       ctx.translate(gr.x, gr.y);
516:       ctx.fillStyle = 'rgba(0,0,0,0.4)';
517:       ctx.beginPath();
518:       ctx.ellipse(0, 4, 7, 3.5, 0, 0, Math.PI * 2);
519:       ctx.fill();
520:       ctx.translate(0, -z);
521:       ctx.rotate(gr.rot);
522:       ctx.fillStyle = '#27331f';
523:       ctx.beginPath();
524:       ctx.arc(0, 0, 5.5, 0, Math.PI * 2);
525:       ctx.fill();
526:       ctx.strokeStyle = '#4b5a38';
527:       ctx.lineWidth = 1;
528:       ctx.stroke();
529:       ctx.fillStyle = '#64734c';
530:       ctx.fillRect(-2, -7, 4, 3);
531:       const blink = Math.sin(g.time * (gr.timer < 0.4 ? 40 : 14)) > 0;
532:       ctx.fillStyle = blink ? '#f87171' : '#5b1d1d';
533:       ctx.beginPath();
534:       ctx.arc(0, 0, 1.8, 0, Math.PI * 2);
535:       ctx.fill();
536:       ctx.restore();
537:     }
538:   }
