540:   drawPlayer() {
541:     const g = this.game;
542:     const p = g.player;
543:     const ctx = this.ctx;
544:     const w = p.weapons[p.slot];
545:     ctx.save();
546:     ctx.translate(p.x, p.y);
547:     // Shadow.
548:     ctx.fillStyle = 'rgba(0,0,0,0.45)';
549:     ctx.beginPath();
550:     ctx.ellipse(2, 7, 16, 8, p.angle, 0, Math.PI * 2);
551:     ctx.fill();
552:     // Selection ring / focus aura.
553:     if (p.focusActive > 0) {
554:       ctx.strokeStyle = `rgba(167,139,250,${0.3 + Math.sin(g.time * 12) * 0.15})`;
555:       ctx.lineWidth = 2;
556:       ctx.beginPath();
557:       ctx.arc(0, 0, 22, 0, Math.PI * 2);
558:       ctx.stroke();
559:     }
560:     ctx.rotate(p.angle);
561:     const step = Math.sin(p.walk) * 3;
562:     // Legs.
563:     ctx.fillStyle = '#1f2a33';
564:     ctx.beginPath();
565:     ctx.ellipse(-5, -5 + step * 0.4, 7, 3.6, 0.25, 0, Math.PI * 2);
566:     ctx.ellipse(-5, 5 - step * 0.4, 7, 3.6, -0.25, 0, Math.PI * 2);
567:     ctx.fill();
568:     // Backpack.
569:     ctx.fillStyle = '#223039';
570:     ctx.fillRect(-14, -6, 7, 12);
571:     ctx.fillStyle = '#38bdf8';
572:     ctx.fillRect(-13, -2, 2, 4);
573:     // Torso.
574:     const grad = ctx.createLinearGradient(-10, 0, 12, 0);
575:     grad.addColorStop(0, '#33424f');
576:     grad.addColorStop(1, '#516271');
577:     ctx.fillStyle = grad;
578:     ctx.beginPath();
579:     ctx.ellipse(0, 0, 12.5, 10.5, 0, 0, Math.PI * 2);
580:     ctx.fill();
581:     ctx.strokeStyle = 'rgba(8,12,16,0.8)';
582:     ctx.lineWidth = 1.4;
583:     ctx.stroke();
584:     // Shoulder plates.
585:     ctx.fillStyle = '#5d7181';
586:     ctx.beginPath();
587:     ctx.ellipse(-1, -8, 5, 3.5, 0.2, 0, Math.PI * 2);
588:     ctx.ellipse(-1, 8, 5, 3.5, -0.2, 0, Math.PI * 2);
589:     ctx.fill();
590:     ctx.fillStyle = 'rgba(56,189,248,0.5)';
591:     ctx.fillRect(-4, -10, 3, 1.2);
592:     ctx.fillRect(-4, 9, 3, 1.2);
593:     // Helmet.
594:     ctx.fillStyle = '#cbd5e1';
595:     ctx.beginPath();
596:     ctx.arc(3, 0, 6.4, 0, Math.PI * 2);
597:     ctx.fill();
598:     ctx.fillStyle = '#1e293b';
599:     ctx.beginPath();
600:     ctx.arc(4, 0, 5, -0.8, 0.8);
601:     ctx.fill();
602:     ctx.fillStyle = '#38bdf8';
603:     ctx.fillRect(7, -2.5, 2, 5);
604:     // Weapon.
605:     const len = w.def.cls === 'MARKSMAN' ? 29 : w.def.cls === 'SHOTGUN' ? 23 : w.def.cls === 'PISTOL' ? 14 : w.def.cls === 'LMG' ? 27 : 23;
606:     ctx.save();
607:     ctx.translate(-p.recoilKick * 0.5, 0);
608:     ctx.fillStyle = '#0e151b';
609:     ctx.fillRect(5, 4.2, len, 3.4);
610:     ctx.fillStyle = '#42525f';
611:     ctx.fillRect(9, 3.2, Math.max(6, len - 12), 2.2);
612:     ctx.fillStyle = '#0e151b';
613:     ctx.fillRect(10, 6.8, 4, 4.8);
614:     if (w.def.cls === 'SHOTGUN') {
615:       ctx.fillStyle = '#6b5236';
616:       ctx.fillRect(16, 3, 8, 4);
617:     }
618:     if (w.def.cls === 'MARKSMAN') {
619:       ctx.fillStyle = '#1e293b';
620:       ctx.fillRect(14, 1.4, 8, 2.2);
621:       ctx.fillStyle = '#a78bfa';
622:       ctx.fillRect(17, 1.8, 3, 1.4);
623:     }
624:     ctx.restore();
625:     if (p.muzzleT > 0) {
626:       ctx.save();
627:       ctx.translate(5 + len, 5.9);
628:       ctx.rotate(randShake(0.4));
629:       const fg = ctx.createRadialGradient(0, 0, 0, 0, 0, 17);
630:       fg.addColorStop(0, 'rgba(255,248,220,0.95)');
631:       fg.addColorStop(0.35, 'rgba(255,196,90,0.7)');
632:       fg.addColorStop(1, 'rgba(255,140,40,0)');
633:       ctx.fillStyle = fg;
634:       ctx.beginPath();
635:       ctx.arc(0, 0, 17, 0, Math.PI * 2);
636:       ctx.fill();
637:       ctx.fillStyle = 'rgba(255,240,200,0.9)';
638:       ctx.beginPath();
639:       ctx.moveTo(0, -3);
640:       ctx.lineTo(12, 0);
641:       ctx.lineTo(0, 3);
642:       ctx.closePath();
643:       ctx.fill();
644:       ctx.restore();
645:     }
646:     ctx.restore();
647:     // Direction chevron.
648:     ctx.save();
649:     ctx.translate(p.x, p.y);
