21: // Segment/circle intersection. Returns the earliest normalised t, or -1.
22: function segCircle(x1, y1, x2, y2, cx, cy, r) {
23:   const dx = x2 - x1;
24:   const dy = y2 - y1;
25:   const fx = x1 - cx;
26:   const fy = y1 - cy;
27:   const a = dx * dx + dy * dy;
28:   if (a < 1e-9) return fx * fx + fy * fy <= r * r ? 0 : -1;
29:   const b = 2 * (fx * dx + fy * dy);
30:   const c = fx * fx + fy * fy - r * r;
31:   const disc = b * b - 4 * a * c;
32:   if (disc < 0) return -1;
33:   const sq = Math.sqrt(disc);
34:   const t1 = (-b - sq) / (2 * a);
35:   if (t1 >= 0 && t1 <= 1) return t1;
36:   const t2 = (-b + sq) / (2 * a);
37:   if (t2 >= 0 && t2 <= 1) return t2;
38:   if (c <= 0) return 0;
39:   return -1;
40: }
