409:   markDecal(type, x, y, angle = 0, scale = 1) {
410:     const ctx = this.decalCtx;
411:     if (!ctx) return;
412:     ctx.save();
413:     ctx.translate(x, y);
414:     ctx.rotate(angle);
415:     if (type === 'blood') {
416:       ctx.fillStyle = `rgba(${Math.round(90 + Math.random() * 40)},${Math.round(10 + Math.random() * 12)},${Math.round(14 + Math.random() * 10)},0.38)`;
417:       for (let i = 0; i < 4; i++) {
418:         ctx.beginPath();
419:         ctx.ellipse(rand(-8, 8), rand(-8, 8), rand(4, 13) * scale, rand(2, 7) * scale, rand(0, 3), 0, Math.PI * 2);
420:         ctx.fill();
421:       }
422:     } else if (type === 'corpse') {
423:       ctx.fillStyle = 'rgba(76,12,16,0.34)';
424:       ctx.beginPath();
425:       ctx.ellipse(0, 0, 26 * scale, 18 * scale, 0, 0, Math.PI * 2);
426:       ctx.fill();
427:       ctx.fillStyle = 'rgba(24,29,34,0.85)';
428:       ctx.beginPath();
429:       ctx.ellipse(0, 0, 16 * scale, 9 * scale, angle, 0, Math.PI * 2);
430:       ctx.fill();
431:       ctx.fillStyle = 'rgba(48,55,62,0.9)';
432:       ctx.beginPath();
433:       ctx.arc(-10 * scale, 0, 6 * scale, 0, Math.PI * 2);
434:       ctx.fill();
435:       ctx.fillStyle = 'rgba(39,45,52,0.8)';
436:       for (let i = 0; i < 2; i++) {
437:         ctx.save();
438:         ctx.rotate(angle + (i ? 1.1 : -1.1));
439:         ctx.fillRect(6 * scale, -3 * scale, 15 * scale, 5 * scale);
440:         ctx.restore();
441:       }
442:       ctx.fillStyle = 'rgba(120,15,20,0.28)';
443:       ctx.beginPath();
444:       ctx.ellipse(rand(-10, 10), rand(-8, 8), 5 * scale, 3 * scale, 0, 0, Math.PI * 2);
445:       ctx.fill();
446:     } else if (type === 'hole') {
447:       ctx.fillStyle = 'rgba(4,6,8,0.65)';
448:       ctx.beginPath();
449:       ctx.arc(0, 0, rand(1.5, 2.6), 0, Math.PI * 2);
450:       ctx.fill();
451:       ctx.fillStyle = 'rgba(190,200,210,0.16)';
452:       ctx.beginPath();
453:       ctx.arc(-0.7, -0.7, 1.1, 0, Math.PI * 2);
454:       ctx.fill();
455:     } else if (type === 'scorch') {
456:       ctx.fillStyle = 'rgba(8,7,6,0.36)';
457:       ctx.beginPath();
458:       ctx.arc(0, 0, 34 * scale, 0, Math.PI * 2);
459:       ctx.fill();
460:       ctx.fillStyle = 'rgba(16,12,8,0.22)';
461:       for (let i = 0; i < 7; i++) {
462:         ctx.beginPath();
463:         ctx.ellipse(rand(-28, 28) * scale, rand(-28, 28) * scale, rand(4, 14) * scale, rand(3, 9) * scale, rand(0, 3), 0, Math.PI * 2);
464:         ctx.fill();
465:       }
466:     }
467:     ctx.restore();
468:   }
