471:   bindGlobalInput() {
472:     window.addEventListener('keydown', (e) => {
473:       if (e.target && ['INPUT', 'TEXTAREA'].includes(e.target.tagName)) return;
474:       const code = e.code;
475:       if (code === 'Escape') {
476:         e.preventDefault();
477:         if (this.ui?.panelKind) {
478:           if (!['results', 'failed'].includes(this.ui.panelKind)) this.ui.closePanel();
479:         } else if (this.state === 'playing') this.pause();
480:         else if (this.state === 'paused') this.resume();
481:         return;
482:       }
483:       if (this.state !== 'playing') return;
484:       if (['Space', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'Tab'].includes(code)) e.preventDefault();
485:       this.input.keys.add(code);
486:       if (code === 'KeyR') this.startReload();
487:       if (code === 'KeyG') this.throwGrenade();
488:       if (code === 'KeyQ') this.activateFocus();
489:       if (code === 'Space') this.dash();
490:       if (code === 'Digit1' || code === 'Digit2') this.swapWeapon();
491:     });
492:     window.addEventListener('keyup', (e) => this.input.keys.delete(e.code));
493:     this.canvas.addEventListener('contextmenu', (e) => e.preventDefault());
494:     this.canvas.addEventListener('pointerdown', (e) => this.onPointerDown(e));
495:     window.addEventListener('pointermove', (e) => this.onPointerMove(e));
496:     window.addEventListener('pointerup', (e) => this.onPointerUp(e));
497:     window.addEventListener('pointercancel', (e) => this.onPointerUp(e));
498:     document.querySelectorAll('#hud [data-action]').forEach((btn) => {
