515:       this.input.mouse.type = 'mouse';
516:       this.updateMouse(e);
517:       return;
518:     }
519:     const rect = this.canvas.getBoundingClientRect();
520:     const x = e.clientX - rect.left;
521:     const y = e.clientY - rect.top;
522:     const side = x < this.renderer.view.w * 0.52 ? 'move' : 'aim';
523:     const stick = {
524:       id: e.pointerId, side, baseX: e.clientX, baseY: e.clientY,
525:       dx: 0, dy: 0, mag: 0, active: true, start: performance.now(),
526:     };
527:     this.input.sticks[side] = stick;
528:     this.ui.showJoystick(stick, side);
529:     this.canvas.setPointerCapture?.(e.pointerId);
