shadeVariants(tex, levels, fog) {
  const fr=fog.r, fg=fog.g, fb=fog.b;
  const out=[];
  for (let l=0;l<levels;l++){
    const t = l/(levels-1);
    const bright = 1 - t*0.86;
    const fogMix = Math.pow(t, 1.35)*0.9;
    const arr = new Uint32Array(tex.w*tex.h);
    for (let i=0;i<arr.length;i++){
      const px=tex.data[i]; const a=(px>>>24);
      if (a===0){arr[i]=0;continue;}
      const r=px&255, g=(px>>>8)&255, b=(px>>>16)&255;
      const nr = Math.round((r*bright)*(1-fogMix)+fr*fogMix);
      ...
      arr[i]= (a<<24)|(nb<<16)|(ng<<8)|nr; // note little endian ABGR
    }
    out.push(arr);
  }
  return out;
}
```
