import { openPage } from './cdp.mjs';

const page = await openPage('http://localhost:8123/index.html');
await page.wait(2000);
await page.evaluate('localStorage.clear(); location.reload();');
await page.wait(2200);
await page.screenshot('/tmp/opencode/fps-11-menu.jpg', 60);
await page.evaluate('game.startMission(0)');
await page.wait(2200);
// Move to a more open part of the map for a representative shot.
await page.evaluate(`(() => {
  const p = game.player;
  const rooms = game.map.rooms || [];
  return { rooms: rooms.length, spawn: { x: p.x, y: p.y } };
})()`);
await page.screenshot('/tmp/opencode/fps-12-start.jpg', 62);
// Look around in 90 degree increments and shoot a few frames each.
for (let i = 0; i < 4; i++) {
  await page.evaluate('game.lookBy(120, 0)');
  await page.wait(280);
  await page.screenshot(`/tmp/opencode/fps-1${3 + i}-look.jpg`, 62);
}
// Frame timing
const perf = await page.evaluate(`(() => {
  const t0 = performance.now();
  for (let i = 0; i < 30; i++) game.renderer.renderGame();
  const t1 = performance.now();
  return { msPerFrame: +((t1 - t0) / 30).toFixed(2) };
})()`);
console.log('PERF', perf);
// Aim at nearest enemy and shoot it.
const hit = await page.evaluate(`(() => {
  const p = game.player;
  let best = null, bd = 1e9;
  for (const e of game.enemies) { if (e.dead) continue; const d = Math.hypot(e.x - p.x, e.y - p.y); if (d < bd) { bd = d; best = e; } }
  if (!best) return null;
  p.angle = Math.atan2(best.y - p.y, best.x - p.x);
  return { name: best.def.name, d: Math.round(bd), hp: best.hp };
})()`);
console.log('TARGET', hit);
await page.wait(400);
const aim = await page.evaluate(`(() => { const t = game.renderer.aimTarget(); return t ? { name: t.enemy.def.name, depth: Math.round(t.depth) } : null; })()`);
console.log('AIM', aim);
await page.screenshot('/tmp/opencode/fps-17-target.jpg', 62);
await page.evaluate('game.input.mouse.down = true');
await page.wait(600);
await page.evaluate('game.input.mouse.down = false');
console.log('AFTERFIRE', await page.evaluate(`({ shots: game.run.shots, hits: game.run.hits, kills: game.run.kills, mag: game.activeWeapon().mag })`));
await page.screenshot('/tmp/opencode/fps-18-combat.jpg', 62);
console.log('ERRORS', page.errors);
page.close();
process.exit(0);

