drawViewmodel() {
  const g = this.game;
  const p = g.player;
  if (!p || p.dead) return;
  const w = p.weapons[p.slot];
  const def = w.def;
  const cls = def.cls;
  const ctx = this.ctx;
  const vw = this.view.w;
  const vh = this.view.h;
  const moving = Math.hypot(p.vx, p.vy) > 35;
  const bob = Math.sin(p.walk * 0.9) * (moving ? 5 : 1.4);
  const bobY = Math.abs(Math.cos(p.walk * 0.9)) * (moving ? 4 : 1);
  const recoil = p.recoilKick;
  const reloadK = w.reloading ? Math.sin(clamp(1 - w.reloadT / def.reload, 0, 1) * Math.PI) : 0;
  const swapK = p.swapT > 0 ? Math.sin((1 - p.swapT / 0.34) * Math.PI) : 0;
  const focus = p.focusActive > 0;
  const pistol = cls === 'PISTOL';
  const s = clamp(Math.min(vw, vh) / 520, 0.72, 2.05) * (pistol ? 0.74 : 1);
  const ox = vw * 0.685 + bob * 0.55 + this.camera.sx * 0.4;
  const oy = vh * 0.985 + bobY + recoil * 1.8 + reloadK * vh * 0.18 + swapK * vh * 0.34 + this.camera.sy * 0.4;
  const muzzleY = pistol ? -152 : cls === 'MARKSMAN' ? -300 : cls === 'LMG' ? -282 : cls === 'SHOTGUN' ? -252 : -262;
  const receiverTop = pistol ? -110 : -142;
  const receiverH = pistol ? 92 : 118;
  ctx.save();
  ctx.translate(ox, oy);
  ctx.rotate(-0.19 + recoil * 0.012 + reloadK * 0.3 - swapK * 0.22);
  ctx.scale(s, s);

  // ---------------------------------------------------------- support arm
  ctx.fillStyle = '#232d36';
  ctx.beginPath();
  ctx.moveTo(26, 52);
  ctx.lineTo(150, 196);
  ctx.lineTo(216, 150);
  ctx.lineTo(84, 12);
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = '#2f3c47';
  ctx.beginPath();
  ctx.moveTo(32, 56);
  ctx.lineTo(146, 182);
  ctx.lineTo(184, 156);
  ctx.lineTo(74, 30);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = 'rgba(0,0,0,0.45)';
  ctx.lineWidth = 2;
  ctx.stroke();

  // -------------------------------------------------------------- stock
  ctx.fillStyle = '#18212a';
  ctx.beginPath();
  ctx.moveTo(-24, receiverTop + receiverH - 16);
  ctx.lineTo(26, receiverTop + receiverH - 16);
  ctx.lineTo(32, receiverTop + receiverH + 62);
  ctx.lineTo(-28, receiverTop + receiverH + 62);
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = '#0e151b';
  ctx.fillRect(-30, receiverTop + receiverH + 46, 64, 20);
  ctx.fillStyle = 'rgba(255,255,255,0.05)';
  ctx.fillRect(-24, receiverTop + receiverH - 12, 48, 2);

  // ------------------------------------------------------- magazine/grip
  ctx.save();
  ctx.translate(2, receiverTop + receiverH - 26);
  ctx.rotate(0.13);
  ctx.fillStyle = cls === 'LMG' ? '#212b1c' : '#141d25';
  rr(ctx, -16, 0, cls === 'LMG' ? 48 : 32, cls === 'LMG' ? 82 : 72, 6);
  ctx.fill();
  ctx.strokeStyle = 'rgba(0,0,0,0.6)';
  ctx.lineWidth = 1.6;
  ctx.stroke();
  ctx.fillStyle = 'rgba(255,255,255,0.07)';
  ctx.fillRect(-11, 8, 18, 3);
  ctx.restore();

  ctx.save();
  ctx.translate(24, receiverTop + receiverH - 34);
  ctx.rotate(0.22);
  ctx.fillStyle = '#121a21';
  rr(ctx, -14, 0, 30, 74, 7);
  ctx.fill();
  ctx.strokeStyle = 'rgba(0,0,0,0.55)';
  ctx.lineWidth = 1.4;
  ctx.stroke();
  ctx.restore();

  // ------------------------------------------------------------ receiver
  const body = ctx.createLinearGradient(-38, 0, 38, 0);
  body.addColorStop(0, '#0d141a');
  body.addColorStop(0.26, '#394854');
  body.addColorStop(0.52, '#51626f');
  body.addColorStop(0.76, '#2b3741');
  body.addColorStop(1, '#0a1015');
  ctx.fillStyle = body;
  rr(ctx, -36, receiverTop, 72, receiverH, 10);
  ctx.fill();
  ctx.strokeStyle = 'rgba(0,0,0,0.6)';
  ctx.lineWidth = 1.8;
  ctx.stroke();
  // Upper rail and ejection port.
  ctx.fillStyle = '#1b252e';
  rr(ctx, -20, receiverTop - 8, 40, 14, 4);
  ctx.fill();
  ctx.fillStyle = 'rgba(0,0,0,0.4)';
  for (let i = 0; i < 6; i++) ctx.fillRect(-18 + i * 7, receiverTop - 5, 2, 8);
  ctx.fillStyle = 'rgba(8,12,16,0.55)';
  rr(ctx, 8, receiverTop + 34, 22, 32, 4);
  ctx.fill();
  // Rim light along the top-left face.
  ctx.fillStyle = 'rgba(203,226,241,0.16)';
  ctx.fillRect(-33, receiverTop + 3, 3, receiverH - 26);

  if (!pistol) {
    // -------------------------------------------------------- handguard
    const guard = ctx.createLinearGradient(-28, 0, 28, 0);
    guard.addColorStop(0, '#0b1117');
    guard.addColorStop(0.34, '#2e3b46');
    guard.addColorStop(0.6, '#3f4f5b');
    guard.addColorStop(1, '#0a0f14');
    ctx.fillStyle = guard;
    rr(ctx, -28, receiverTop - 82, 56, 92, 9);
    ctx.fill();
    ctx.strokeStyle = 'rgba(0,0,0,0.5)';
    ctx.lineWidth = 1.4;
    ctx.stroke();
    ctx.fillStyle = 'rgba(0,0,0,0.4)';
    for (let i = 0; i < 4; i++) ctx.fillRect(-22, receiverTop - 70 + i * 15, 44, 5);
    ctx.fillStyle = 'rgba(210,232,246,0.1)';
    ctx.fillRect(-25, receiverTop - 79, 2, 84);
    // ------------------------------------------------------------- barrel
    ctx.fillStyle = '#0a0f14';
    rr(ctx, -11, muzzleY, 22, receiverTop - 60 - muzzleY, 5);
    ctx.fill();
    ctx.fillStyle = 'rgba(190,214,229,0.12)';
    ctx.fillRect(-9, muzzleY + 4, 3, receiverTop - 70 - muzzleY);
    // Muzzle brake.
    ctx.fillStyle = '#131c23';
    rr(ctx, -14, muzzleY - 16, 28, 22, 4);
    ctx.fill();
    ctx.fillStyle = 'rgba(0,0,0,0.55)';
    ctx.fillRect(-14, muzzleY - 6, 28, 2);
    ctx.fillRect(-14, muzzleY + 1, 28, 2);
    // Optic.
    ctx.fillStyle = '#0b1117';
    rr(ctx, -21, receiverTop - 44, 42, 34, 6);
    ctx.fill();
    ctx.strokeStyle = 'rgba(0,0,0,0.6)';
    ctx.lineWidth = 1.4;
    ctx.stroke();
    const lens = ctx.createRadialGradient(-3, receiverTop - 30, 1, -3, receiverTop - 30, 11);
    lens.addColorStop(0, focus ? 'rgba(221,214,254,0.95)' : 'rgba(125,211,252,0.8)');
    lens.addColorStop(0.6, focus ? 'rgba(124,58,237,0.45)' : 'rgba(14,116,144,0.45)');
    lens.addColorStop(1, 'rgba(4,10,16,0.9)');
    ctx.fillStyle = lens;
    ctx.beginPath();
    ctx.arc(-3, receiverTop - 27, 10, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = 'rgba(255,255,255,0.25)';
    ctx.beginPath();
    ctx.arc(-6, receiverTop - 30, 3.2, 0, Math.PI * 2);
    ctx.fill();
  } else {
    ctx.fillStyle = '#0a0f14';
    rr(ctx, -10, muzzleY, 20, receiverTop - 6 - muzzleY, 4);
    ctx.fill();
    ctx.fillStyle = 'rgba(190,214,229,0.12)';
    ctx.fillRect(-8, muzzleY + 3, 3, receiverTop - 16 - muzzleY);
  }

  // ------------------------------------------------------- gloved hands
  ctx.fillStyle = '#39464f';
  rr(ctx, -34, receiverTop - 78, 68, 34, 13);
  ctx.fill();
  ctx.strokeStyle = 'rgba(0,0,0,0.4)';
  ctx.lineWidth = 1.3;
  ctx.stroke();
  ctx.fillStyle = '#2a343d';
  for (let i = 0; i < 3; i++) rr(ctx, -28 + i * 20, receiverTop - 74, 15, 27, 6), ctx.fill();
  ctx.fillStyle = 'rgba(255,255,255,0.08)';
  ctx.fillRect(-30, receiverTop - 74, 58, 2);

  ctx.fillStyle = '#39464f';
  rr(ctx, 6, receiverTop + receiverH - 46, 44, 40, 14);
  ctx.fill();
  ctx.strokeStyle = 'rgba(0,0,0,0.4)';
  ctx.stroke();
  ctx.fillStyle = '#2a343d';
  for (let i = 0; i < 3; i++) rr(ctx, 11 + i * 11, receiverTop + receiverH - 41, 9, 31, 5), ctx.fill();

  // --------------------------------------------------------- muzzle flash
  if (p.muzzleT > 0) {
    const mx = 0;
    const my = muzzleY - 20;
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    const flash = ctx.createRadialGradient(mx, my, 0, mx, my, 62);
    flash.addColorStop(0, 'rgba(255,250,225,0.95)');
    flash.addColorStop(0.22, 'rgba(255,196,90,0.72)');
    flash.addColorStop(1, 'rgba(255,120,30,0)');
    ctx.fillStyle = flash;
    ctx.beginPath();
    ctx.arc(mx, my, 62, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = 'rgba(255,244,210,0.92)';
    ctx.beginPath();
    ctx.moveTo(mx, my - 14);
    ctx.lineTo(mx + 42, my);
    ctx.lineTo(mx, my + 14);
    ctx.lineTo(mx - 42, my);
    ctx.closePath();
    ctx.fill();
    ctx.fillStyle = 'rgba(255,255,240,0.95)';
    ctx.beginPath();
    ctx.arc(mx, my, 6, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  }
  ctx.restore();

  // Muzzle light thrown into the scene.
  if (p.muzzleT > 0) {
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    const glow = ctx.createRadialGradient(vw * 0.56, vh * 0.58, 0, vw * 0.56, vh * 0.58, vh * 0.72);
    glow.addColorStop(0, 'rgba(255,190,110,0.09)');
    glow.addColorStop(1, 'rgba(255,150,60,0)');
    ctx.fillStyle = glow;
    ctx.fillRect(0, 0, vw, vh);
    ctx.restore();
  }
}

