  const p = game.player;
  const e = game.enemies.find((x) => !x.dead);
  let best = null;
  for (let a = 0; a < Math.PI * 2; a += Math.PI / 8) {
    const x = e.x + Math.cos(a) * 180;
    const y = e.y + Math.sin(a) * 180;
    if (game.map.solidAt(x, y)) continue;
    const hit = game.map.raycast(x, y, e.x, e.y, 400);
    if (hit && hit.dist < 170) continue;
    best = { x, y };
    break;
  }
  if (best) { p.x = best.x; p.y = best.y; p.angle = Math.atan2(e.y - p.y, e.x - p.x); }
  return { enemy: { name: e.def.name, hp: e.hp }, placed: best, angle: p.angle };
})()`);
console.log('PLACE', info);
await page.wait(500);
console.log('PROJ', await page.evaluate(`(() => {
  const p = game.player, r = game.renderer;
  const e = game.enemies.find((x) => !x.dead);
  const pr = r.project(e.x, e.y, 23);
  const col = pr ? Math.max(0, Math.min(r.bw - 1, Math.floor((pr.x / r.view.w) * r.bw))) : -1;
