await page.evaluate('game.input.mouse.down = true');
await page.wait(900);
await page.evaluate('game.input.mouse.down = false');
await page.wait(300);
console.log('SHOOT', await page.evaluate(`({ shots: game.run.shots, hits: game.run.hits, kills: game.run.kills, mag: game.activeWeapon().mag })`));
await page.screenshot('/tmp/opencode/fps-22-enemy-hit.jpg', 65);
console.log('ERRORS', page.errors);
page.close();
process.exit(0);

