await page.evaluate('game.startMission(0)');
await page.wait(1400);
const info = await page.evaluate(`(() => {
  const p = game.player;
  const live = game.enemies.filter((e) => !e.dead);
  const e = live[0];
  for (const other of live.slice(1)) { other.dead = true; other.hp = 0; }
  // Freeze the target so the projection is stable for the check.
  e.speed = 0; e.alerted = true;
  let placed = null;
  for (let a = 0; a < Math.PI * 2; a += Math.PI / 16) {
    const x = e.x + Math.cos(a) * 210;
    const y = e.y + Math.sin(a) * 210;
    if (game.map.solidAt(x, y)) continue;
    const hit = game.map.raycast(x, y, e.x, e.y, 400);
    if (hit && hit.dist < 200) continue;
    placed = { x, y };
    break;
  }
  if (placed) { p.x = placed.x; p.y = placed.y; p.angle = Math.atan2(e.y - p.y, e.x - p.x); }
  return { placed, enemy: { x: e.x, y: e.y, r: e.r }, depth: placed ? Math.hypot(e.x - p.x, e.y - p.y) : 0 };
})()`);
await page.wait(400);
const check = await page.evaluate(`(() => {
  const r = game.renderer, p = game.player;
  const e = game.enemies.find((x) => !x.dead);
  const bot = r.project(e.x, e.y, 0);
  const top = r.project(e.x, e.y, 46);
  return { bot: bot && { x: Math.round(bot.x), y: Math.round(bot.y) }, top: top && { x: Math.round(top.x), y: Math.round(top.y) }, aim: !!r.aimTarget() };
})()`);
console.log('TARGET', info, check);
await page.screenshot('/tmp/opencode/fps-95-target.jpg', 64);
console.log('ERRORS', page.errors);
page.close();
process.exit(0);

