1333:   // ------------------------------------------------------------------ bullets
1334:   updateBullets(dt) {
1335:     const p = this.player;
1336:     for (let i = this.bullets.length - 1; i >= 0; i--) {
1337:       const b = this.bullets[i];
1338:       b.life -= dt;
1339:       if (b.life <= 0) {
1340:         this.bullets.splice(i, 1);
1341:         continue;
1342:       }
1343:       const step = b.speed * dt;
1344:       if (step <= 0.01) continue;
1345:       const nx = b.vx / b.speed;
1346:       const ny = b.vy / b.speed;
1347:       const endX = b.x + nx * step;
1348:       const endY = b.y + ny * step;
1349:       const wallHit = this.map.raycast(b.x, b.y, endX, endY, step);
1350:       let actor = null;
1351:       let actorT = 1;
1352:       if (b.owner === 'player') {
1353:         for (const e of this.enemies) {
1354:           if (e.dead) continue;
1355:           const t = segCircle(b.x, b.y, endX, endY, e.x, e.y, e.r + 2);
1356:           if (t >= 0 && t < actorT) {
1357:             actorT = t;
1358:             actor = e;
1359:           }
1360:         }
1361:       } else if (p && !p.dead && p.invuln <= 0) {
1362:         const t = segCircle(b.x, b.y, endX, endY, p.x, p.y, p.r + 1);
1363:         if (t >= 0) {
1364:           actorT = t;
1365:           actor = p;
1366:         }
1367:       }
1368:       const wallT = wallHit ? wallHit.dist / step : 1;
1369:       if (actor && actorT <= wallT) {
1370:         const hx = b.x + nx * step * actorT;
1371:         const hy = b.y + ny * step * actorT;
1372:         if (b.owner === 'player') {
1373:           const head = Math.random() < 0.1;
1374:           this.damageEnemy(actor, b.dmg * (1 + b.traveled / 5000), b.angle, head, hx, hy, true);
1375:           this.run.hits++;
1376:           this.hitMarker = 0.16;
1377:           this.hitMarkerHead = head;
1378:           this.audio.hitmarker(head);
1379:         } else {
1380:           this.damagePlayer(b.dmg, b.angle, hx, hy);
1381:         }
1382:         this.bullets.splice(i, 1);
1383:         continue;
1384:       }
1385:       if (wallHit) {
1386:         this.handleBulletWall(b, wallHit, nx, ny, i);
1387:         continue;
1388:       }
1389:       b.x = endX;
1390:       b.y = endY;
1391:       b.traveled += step;
1392:       if (b.x < 0 || b.y < 0 || b.x > WORLD_W || b.y > WORLD_H) this.bullets.splice(i, 1);
1393:     }
1394:   }
1395: 
1396:   handleBulletWall(b, hit, nx, ny, index) {
1397:     const thresholds = { 1: 3, 2: 1, 3: 2, 4: 0, 5: 4 };
1398:     const mults = { 1: 0.32, 2: 0.62, 3: 0.45, 4: 0.2, 5: 0.35 };
1399:     const threshold = thresholds[hit.tile] ?? 3;
1400:     const isBarrel = hit.tile === 4;
1401:     const speed = b.speed;
1402:     const dot = (nx * hit.nx + ny * hit.ny);
1403:     const shallow = Math.abs(dot) < 0.62;
1404:     if (!isBarrel && shallow && b.ricochets < 1 && speed > 650 && Math.random() < 0.3) {
1405:       const d = nx * hit.nx + ny * hit.ny;
1406:       const rx = nx - 2 * d * hit.nx;
1407:       const ry = ny - 2 * d * hit.ny;
1408:       b.x = hit.x + hit.nx * 4;
1409:       b.y = hit.y + hit.ny * 4;
1410:       b.vx = rx * speed * 0.62;
1411:       b.vy = ry * speed * 0.62;
1412:       b.speed = speed * 0.62;
1413:       b.dmg *= 0.7;
1414:       b.ricochets++;
1415:       b.pen = Math.max(0, b.pen - 1);
1416:       this.audio.ricochet(this.renderer.panFor(hit.x, hit.y));
1417:       for (let i = 0; i < 4; i++) {
1418:         this.particles.push({
1419:           type: 'spark', x: hit.x, y: hit.y,
1420:           vx: hit.nx * rand(60, 220) + rand(-80, 80), vy: hit.ny * rand(60, 220) + rand(-80, 80),
1421:           life: rand(0.1, 0.25), max: 0.25, size: rand(1, 2), color: '#ffd28a',
1422:         });
1423:       }
1424:       return;
1425:     }
1426:     const prop = this.map.hp.get(hit.ty * 50 + hit.tx);
1427:     if (prop) {
1428:       const res = this.map.damageTile(hit.tx, hit.ty, b.dmg * 1.8);
1429:       if (res?.destroyed) {
1430:         if (res.type === 4) {
1431:           const cxp = hit.tx * 40 + 20;
1432:           const cyp = hit.ty * 40 + 20;
1433:           this.chain.push({ x: cxp, y: cyp, t: 0.06 });
1434:         } else {
1435:           this.debris(hit.tx, hit.ty, res.type);
1436:         }
1437:       }
1438:     }
1439:     if (b.pen >= threshold) {
1440:       b.x = hit.x + nx * 5;
1441:       b.y = hit.y + ny * 5;
1442:       b.dmg *= mults[hit.tile] ?? 0.4;
1443:       b.speed *= 0.82;
1444:       b.vx *= 0.82;
1445:       b.vy *= 0.82;
1446:       b.pen = Math.max(0, b.pen - 1);
1447:       this.particles.push({
1448:         type: 'debris', x: hit.x, y: hit.y, vx: hit.nx * rand(20, 100), vy: hit.ny * rand(20, 100),
1449:         life: 0.4, max: 0.4, size: rand(1, 2.5), color: '#b8c4cf', rot: rand(0, 6), spin: rand(-8, 8),
1450:       });
1451:       return;
1452:     }
1453:     this.markDecal('hole', hit.x, hit.y, rand(0, 6));
1454:     this.bullets.splice(index, 1);
1455:     this.audio.impact(this.renderer.panFor(hit.x, hit.y));
1456:     for (let i = 0; i < 3; i++) {
1457:       this.particles.push({
1458:         type: 'spark', x: hit.x, y: hit.y,
1459:         vx: hit.nx * rand(40, 150) + rand(-60, 60), vy: hit.ny * rand(40, 150) + rand(-60, 60),
1460:         life: rand(0.08, 0.2), max: 0.2, size: rand(1, 2), color: '#ffcf7a',
1461:       });
1462:     }
1463:   }
