1638:   explode(x, y, radius, damage) {
1639:     this.audio.explosion(this.renderer.panFor(x, y));
1640:     this.renderer.shake(16);
1641:     this.markDecal('scorch', x, y, 0, radius / 100);
1642:     this.particles.push({ type: 'ring', x, y, vx: 0, vy: 0, life: 0.42, max: 0.42, size: radius, color: '#ffb36b' });
1643:     this.particles.push({ type: 'flash', x, y, vx: 0, vy: 0, life: 0.28, max: 0.28, size: radius * 1.5, color: '#ffd28a' });
1644:     for (let i = 0; i < 30; i++) {
1645:       const a = rand(0, Math.PI * 2);
1646:       const sp = rand(80, 420);
1647:       this.particles.push({
1648:         type: 'spark', x, y, vx: Math.cos(a) * sp, vy: Math.sin(a) * sp,
1649:         life: rand(0.2, 0.7), max: 0.7, size: rand(1, 3.2), color: pick(['#ffd28a', '#ff9a3c', '#fff3d6']),
1650:       });
1651:     }
1652:     for (let i = 0; i < 18; i++) {
1653:       this.particles.push({
1654:         type: 'smoke', x: x + rand(-30, 30), y: y + rand(-30, 30),
1655:         vx: rand(-50, 50), vy: rand(-50, 50), life: rand(0.6, 1.4), max: 1.4,
1656:         size: rand(10, 26), color: '#3a3530', alpha: 0.28,
1657:       });
1658:     }
1659:     for (const e of this.enemies) {
1660:       if (e.dead) continue;
1661:       const d = dist(x, y, e.x, e.y);
1662:       if (d > radius + e.r) continue;
1663:       let falloff = 1 - clamp(d / radius, 0, 1);
1664:       const visible = this.map.los(x, y, e.x, e.y);
1665:       if (!visible) falloff *= 0.45;
1666:       if (falloff > 0.04) this.damageEnemy(e, damage * falloff, Math.atan2(e.y - y, e.x - x), false, e.x, e.y, false);
1667:     }
1668:     const p = this.player;
1669:     if (p && !p.dead) {
1670:       const d = dist(x, y, p.x, p.y);
1671:       if (d < 90) this.damagePlayer((1 - d / 90) * 26, Math.atan2(p.y - y, p.x - x), p.x, p.y);
1672:     }
1673:     // Blow apart props, triggering chain reactions for fuel barrels.
1674:     const minTx = Math.floor((x - radius) / 40);
1675:     const maxTx = Math.floor((x + radius) / 40);
1676:     const minTy = Math.floor((y - radius) / 40);
1677:     const maxTy = Math.floor((y + radius) / 40);
1678:     for (let ty = minTy; ty <= maxTy; ty++) {
1679:       for (let tx = minTx; tx <= maxTx; tx++) {
1680:         if (!this.map.hp.has(ty * 50 + tx)) continue;
1681:         const cx = tx * 40 + 20;
1682:         const cy = ty * 40 + 20;
1683:         const d = Math.hypot(cx - x, cy - y);
1684:         if (d > radius) continue;
1685:         const res = this.map.damageTile(tx, ty, damage * (1 - d / radius) * 2);
1686:         if (res?.destroyed) {
1687:           if (res.type === 4) this.chain.push({ x: cx, y: cy, t: rand(0.08, 0.3) });
1688:           else this.debris(tx, ty, res.type);
1689:         }
1690:       }
1691:     }
1692:   }
