1809:   spawnWave() {
1810:     this.wave++;
1811:     const n = this.wave;
1812:     const comp = {
1813:       grunt: Math.min(10, 3 + Math.ceil(n * 0.7)),
1814:       scout: Math.min(5, Math.floor(n / 2)),
1815:       marksman: Math.min(4, Math.floor(n / 3)),
1816:       heavy: Math.min(3, Math.floor(n / 4)),
1817:     };
1818:     const types = [];
1819:     for (const [type, count] of Object.entries(comp)) for (let i = 0; i < count; i++) types.push(type);
1820:     const p = this.player;
1821:     const rooms = this.map.rooms.filter((r) => r.index !== this.map.spawnRoom.index);
1822:     for (const type of types) {
1823:       for (let attempt = 0; attempt < 30; attempt++) {
1824:         const room = pick(rooms);
1825:         const spot = this.map.randomFreeSpot(room, Math.random);
1826:         if (!spot) continue;
1827:         if (dist(spot.x, spot.y, p.x, p.y) < 430) continue;
1828:         const e = this.createEnemy(type, spot.x, spot.y, room.index);
1829:         e.state = 'search';
1830:         e.alert = 1;
