918:     this.updateEnemies(wdt);
919:     this.updateBullets(wdt);
920:     this.updateGrenades(wdt);
921:     this.updateParticles(wdt);
922:     this.updatePickups(wdt);
923:     this.updateTexts(wdt);
924:     this.updateChain(wdt);
925:     this.checkObjectives(wdt);
926:     this.damageFlash = Math.max(0, this.damageFlash - dt * 2.4);
927:     this.hitMarker = Math.max(0, this.hitMarker - dt);
928:     if (this.wavePending) {
929:       this.waveTimer -= dt;
930:       if (this.waveTimer <= 0) {
931:         this.wavePending = false;
932:         this.spawnWave();
933:       }
934:     }
935:     this.audio.setMusicIntensity(clamp(0.5 + this.aliveCount() * 0.05, 0.4, 1));
936:   }
