938:   updatePlayer(dt, realDt) {
939:     const p = this.player;
940:     if (!p || p.dead) return;
941:     const w = this.activeWeapon();
942:     p.swapT = Math.max(0, p.swapT - realDt);
943:     p.fireCd = Math.max(0, p.fireCd - dt);
944:     p.recoilKick = damp(p.recoilKick, 0, 16, dt);
945:     p.heat = damp(p.heat, 0, 3.6, dt);
946:     p.muzzleT = Math.max(0, p.muzzleT - realDt);
947:     if (w.reloading) {
948:       w.reloadT -= dt;
949:       if (w.reloadT <= 0) this.finishReload(w);
950:     }
951:     const move = this.getMoveInput();
952:     this.applyLook(realDt);
953:     const aim = this.getAimInput();
954:     if (aim.firing && (aim.mode === 'pad' || aim.mode === 'touch')) {
955:       p.angle = angleLerp(p.angle, this.aimAssistAngle(p.angle), 1 - Math.exp(-3.2 * realDt));
956:     }
957:     p.lookT = Math.max(0, (p.lookT || 0) - realDt);
958:     let speed = p.speed * (move.sprint && !this.isTouch ? 1.3 : 1);
959:     let tx = 0;
960:     let ty = 0;
961:     if (p.dashT > 0) {
962:       p.dashT -= realDt;
963:       speed = 760;
964:       tx = p.dashX * speed;
965:       ty = p.dashY * speed;
966:       if (Math.random() < 0.6) {
967:         this.particles.push({
968:           type: 'smoke', x: p.x, y: p.y, vx: rand(-20, 20), vy: rand(-20, 20),
969:           life: 0.28, max: 0.28, size: rand(4, 8), color: '#7dd3fc', alpha: 0.16,
970:         });
971:       }
972:     } else if (move.moving) {
973:       tx = move.x * speed;
974:       ty = move.y * speed;
975:       p.walk += dt * speed * 0.055;
976:       if (Math.random() < 0.09) {
977:         this.particles.push({
978:           type: 'smoke', x: p.x + rand(-6, 6), y: p.y + 10, vx: rand(-8, 8), vy: rand(-8, 2),
979:           life: 0.45, max: 0.45, size: rand(2, 4), color: this.map.palette.dust, alpha: 0.08,
980:         });
981:       }
982:     }
983:     p.vx = damp(p.vx, tx, p.dashT > 0 ? 30 : 12, dt);
984:     p.vy = damp(p.vy, ty, p.dashT > 0 ? 30 : 12, dt);
985:     p.x += p.vx * dt;
986:     p.y += p.vy * dt;
987:     const resolved = this.map.resolveCircle(p.x, p.y, p.r);
988:     p.x = clamp(resolved.x, 20, WORLD_W - 20);
989:     p.y = clamp(resolved.y, 20, WORLD_H - 20);
990:     if (resolved.hit && Math.hypot(p.vx, p.vy) > 200) {
991:       p.vx *= 0.4;
992:       p.vy *= 0.4;
993:     }
994:     if (aim.firing) this.firePlayer();
995:     if (p.hp <= 0 && !p.dead) this.playerDown();
996:   }
