998:   firePlayer() {
999:     const p = this.player;
1000:     if (!p || p.swapT > 0) return;
1001:     const w = this.activeWeapon();
1002:     if (w.reloading || p.fireCd > 0) return;
1003:     if (w.mag <= 0) {
1004:       this.audio.empty();
1005:       if (w.reserve > 0) this.startReload();
1006:       else if (!p.emptyHinted) {
1007:         p.emptyHinted = true;
1008:         this.ui.showTip('OUT OF AMMO — PRESS R OR SCAVENGE', 2200);
1009:       }
1010:       p.fireCd = 0.25;
1011:       return;
1012:     }
1013:     const aim = this.getAimInput(0.016, true);
1014:     const moving = Math.hypot(p.vx, p.vy) > 40;
1015:     let spread = w.def.spread + p.heat * 0.7 + (moving ? 1.1 : 0);
1016:     if (p.focusActive > 0) spread *= 0.72;
1017:     const muzzleX = p.x + Math.cos(p.angle) * 22;
1018:     const muzzleY = p.y + Math.sin(p.angle) * 22;
1019:     const pellets = w.def.pellets || 1;
1020:     for (let i = 0; i < pellets; i++) {
1021:       const a = p.angle + deg((Math.random() - 0.5) * spread * 2);
1022:       const speed = w.def.velocity * rand(0.97, 1.03);
1023:       this.bullets.push({
1024:         x: muzzleX + Math.cos(a) * rand(0, 5), y: muzzleY + Math.sin(a) * rand(0, 5),
1025:         vx: Math.cos(a) * speed, vy: Math.sin(a) * speed, speed,
1026:         dmg: w.def.dmg * rand(0.92, 1.08), pen: w.def.pen,
1027:         owner: 'player', color: w.def.color, life: 2.4, traveled: 0,
1028:         ricochets: 0, tracer: Math.random() < 0.65, angle: a, weaponId: w.def.id,
1029:       });
1030:       this.run.shots++;
1031:     }
1032:     w.mag--;
1033:     p.fireCd = 60 / w.def.rpm;
1034:     p.heat = Math.min(9, p.heat + w.def.recoil * 0.75);
1035:     p.muzzleT = 0.055;
1036:     p.muzzleAngle = p.angle;
1037:     p.recoilKick = 4;
1038:     for (let i = 0; i < 4; i++) {
1039:       this.particles.push({
1040:         type: 'spark', x: muzzleX, y: muzzleY,
1041:         vx: Math.cos(p.angle + rand(-0.35, 0.35)) * rand(100, 300),
1042:         vy: Math.sin(p.angle + rand(-0.35, 0.35)) * rand(100, 300),
1043:         life: rand(0.08, 0.18), max: 0.18, size: rand(1, 2.4), color: '#ffd28a',
1044:       });
1045:     }
1046:     this.particles.push({
1047:       type: 'flash', x: muzzleX, y: muzzleY, vx: 0, vy: 0,
1048:       life: 0.07, max: 0.07, size: 22, color: w.def.color,
1049:     });
1050:     this.particles.push({
1051:       type: 'casing', x: p.x + Math.cos(p.angle + 1.7) * 12, y: p.y + Math.sin(p.angle + 1.7) * 12,
1052:       vx: Math.cos(p.angle + 1.7) * rand(40, 90), vy: Math.sin(p.angle + 1.7) * rand(40, 90),
1053:       life: 1.1, max: 1.1, size: 2.2, rot: rand(0, 6), spin: rand(-14, 14), color: '#e0a94a',
1054:     });
1055:     this.audio.shoot(w.def.sound, { suppressed: Boolean(w.def.suppressed), pan: 0 });
1056:     this.renderer.shake((w.def.recoil + 0.4) * 0.75);
1057:     this.makeNoise(p.x, p.y, w.def.suppressed ? 300 : 760);
1058:     if (w.mag === 0 && w.reserve > 0) this.startReload();
1059:     this.ui.updateHUD();
1060:   }
