1062:   // ------------------------------------------------------------------- enemies
1063:   aliveCount() {
1064:     return this.enemies.filter((e) => !e.dead).length;
1065:   }
1066: 
1067:   enemyCanSee(e) {
1068:     const p = this.player;
1069:     if (!p || p.dead) return false;
1070:     const d = dist(e.x, e.y, p.x, p.y);
1071:     if (d > e.def.vision) return false;
1072:     if (d < 150) return true;
1073:     const a = Math.atan2(p.y - e.y, p.x - e.x);
1074:     const diff = Math.abs(Math.atan2(Math.sin(a - e.angle), Math.cos(a - e.angle)));
1075:     if (diff > e.def.cone) return false;
1076:     return this.map.los(e.x, e.y, p.x, p.y);
1077:   }
1078: 
1079:   makeNoise(x, y, radius) {
1080:     for (const e of this.enemies) {
1081:       if (e.dead) continue;
1082:       const d = dist(x, y, e.x, e.y);
1083:       if (d > radius) continue;
1084:       e.alert = 1;
1085:       e.alertFlash = Math.max(e.alertFlash, 0.9);
1086:       e.lastKnown = {
1087:         x: x + rand(-90, 90),
1088:         y: y + rand(-90, 90),
1089:       };
1090:       if (e.state === 'patrol') {
1091:         e.state = 'search';
1092:         e.searchT = 0;
1093:         e.pathT = 0;
1094:       }
1095:     }
1096:   }
1097: 
1098:   alertEnemy(e) {
1099:     if (e.alert < 0.9) {
1100:       e.alert = 1;
1101:       e.alertFlash = 1.1;
1102:       if (this.worldTime - this.lastAlertSound > 2.2) {
1103:         this.lastAlertSound = this.worldTime;
1104:         this.audio.alert();
1105:       }
1106:     }
1107:     e.state = 'engage';
1108:     e.lastKnown = { x: this.player.x, y: this.player.y };
1109:     e.lastSeen = this.worldTime;
1110:   }
1111: 
1112:   updateEnemies(dt) {
1113:     const p = this.player;
1114:     for (const e of this.enemies) {
1115:       if (e.dead) continue;
1116:       e.hitFlash = Math.max(0, e.hitFlash - dt);
1117:       e.alertFlash = Math.max(0, e.alertFlash - dt);
1118:       e.muzzleT = Math.max(0, e.muzzleT - dt);
1119:       e.spawnFx = Math.max(0, e.spawnFx - dt);
1120:       e.reloadT = Math.max(0, e.reloadT - dt);
1121:       e.alert = Math.max(0, e.alert - dt * 0.03);
1122:       const d = dist(e.x, e.y, p.x, p.y);
1123:       const canSee = this.enemyCanSee(e);
1124:       e.canSee = canSee;
1125:       if (canSee) {
1126:         e.alertFlash = Math.max(e.alertFlash, 0.2);
1127:         if (e.state !== 'engage') this.alertEnemy(e);
1128:         else {
1129:           e.alert = 1;
1130:           e.lastSeen = this.worldTime;
1131:           e.lastKnown = { x: p.x, y: p.y };
1132:         }
1133:       }
1134:       if (e.state === 'patrol') {
1135:         this.updatePatrol(e, dt);
1136:       } else if (e.state === 'engage') {
1137:         if (canSee) this.updateCombatMove(e, d, dt);
1138:         else {
1139:           this.updatePathMove(e, e.lastKnown.x, e.lastKnown.y, e.def.speed * 0.82, dt);
1140:           if (this.worldTime - e.lastSeen > 2.3) {
1141:             e.state = 'search';
1142:             e.searchT = 0;
1143:           }
1144:         }
1145:       } else if (e.state === 'search') {
1146:         e.searchT += dt;
1147:         if (canSee) {
1148:           this.alertEnemy(e);
1149:         } else if (e.lastKnown) {
1150:           this.updatePathMove(e, e.lastKnown.x, e.lastKnown.y, e.def.speed * 0.72, dt);
1151:           const near = dist(e.x, e.y, e.lastKnown.x, e.lastKnown.y) < 50;
1152:           if ((near && e.searchT > 3) || e.searchT > 12) {
1153:             e.state = 'patrol';
1154:             e.path = [];
1155:             e.pathT = 0;
1156:             e.alert = 0.3;
1157:           }
1158:         }
1159:       }
1160:       if (e.state === 'engage' && canSee && d < e.def.range) this.updateEnemyFire(e, d, dt);
1161:       // Resolve against geometry.
1162:       const res = this.map.resolveCircle(e.x, e.y, e.r);
1163:       e.x = res.x;
1164:       e.y = res.y;
1165:     }
1166:     // Soft separation so squads do not stack into one silhouette.
1167:     for (let i = 0; i < this.enemies.length; i++) {
1168:       const a = this.enemies[i];
1169:       if (a.dead) continue;
1170:       for (let j = i + 1; j < this.enemies.length; j++) {
1171:         const b = this.enemies[j];
1172:         if (b.dead) continue;
1173:         const dx = b.x - a.x;
1174:         const dy = b.y - a.y;
1175:         const d = Math.hypot(dx, dy);
1176:         const min = a.r + b.r + 4;
1177:         if (d > 0.001 && d < min) {
1178:           const push = (min - d) * 0.5;
1179:           a.x -= (dx / d) * push;
1180:           a.y -= (dy / d) * push;
1181:           b.x += (dx / d) * push;
1182:           b.y += (dy / d) * push;
1183:         }
1184:       }
1185:     }
1186:   }
1187: 
1188:   updatePatrol(e, dt) {
1189:     e.pathT -= dt;
1190:     if (!e.patrol) {
1191:       e.patrol = { x: e.homeX, y: e.homeY, t: 0 };
1192:     }
1193:     e.patrol.t -= dt;
1194:     if (e.patrol.t <= 0) {
1195:       const room = this.map.rooms[e.room] || this.map.rooms[0];
1196:       const spot = this.map.randomFreeSpot(room, Math.random);
1197:       e.patrol.x = spot ? spot.x : e.homeX;
1198:       e.patrol.y = spot ? spot.y : e.homeY;
1199:       e.patrol.t = rand(3.5, 7);
1200:       e.pathT = 0;
1201:     }
1202:     this.updatePathMove(e, e.patrol.x, e.patrol.y, e.def.speed * 0.42, dt, true);
1203:   }
1204: 
1205:   updateCombatMove(e, d, dt) {
1206:     const p = this.player;
1207:     const pref = e.type === 'marksman' ? [520, 820] : e.type === 'heavy' ? [200, 340] : e.type === 'scout' ? [100, 230] : [200, 400];
1208:     e.strafeT -= dt;
1209:     if (e.strafeT <= 0) {
1210:       e.strafe *= -1;
1211:       e.strafeT = rand(0.8, 2.2);
1212:     }
1213:     let mx = 0;
1214:     let my = 0;
1215:     if (d > pref[1]) {
1216:       mx = (p.x - e.x) / d;
1217:       my = (p.y - e.y) / d;
1218:     } else if (d < pref[0]) {
1219:       mx = (e.x - p.x) / (d || 1);
1220:       my = (e.y - p.y) / (d || 1);
1221:     } else {
1222:       mx = (-(p.y - e.y) / (d || 1)) * e.strafe;
1223:       my = ((p.x - e.x) / (d || 1)) * e.strafe;
1224:     }
1225:     const speed = e.def.speed * 0.72;
1226:     e.vx = damp(e.vx, mx * speed, 9, dt);
1227:     e.vy = damp(e.vy, my * speed, 9, dt);
1228:     e.x += e.vx * dt;
1229:     e.y += e.vy * dt;
1230:     e.angle = angleLerp(e.angle, Math.atan2(p.y - e.y, p.x - e.x), 1 - Math.exp(-6 * dt));
1231:     e.walk += dt * speed * 0.05;
1232:     e.path = [];
1233:   }
1234: 
1235:   updatePathMove(e, tx, ty, speed, dt, idle = false) {
1236:     const p = this.player;
1237:     if (!idle && e.canSee && dist(e.x, e.y, tx, ty) < 460) {
1238:       // Clear line: walk directly, which feels far more deliberate than tile paths.
1239:       const a = Math.atan2(ty - e.y, tx - e.x);
1240:       e.vx = damp(e.vx, Math.cos(a) * speed, 8, dt);
1241:       e.vy = damp(e.vy, Math.sin(a) * speed, 8, dt);
1242:       e.x += e.vx * dt;
1243:       e.y += e.vy * dt;
1244:       e.angle = angleLerp(e.angle, a, 1 - Math.exp(-7 * dt));
1245:       e.walk += dt * speed * 0.05;
1246:       return;
1247:     }
1248:     e.pathT -= dt;
1249:     if (e.pathT <= 0 || !e.pathTarget || dist(e.pathTarget.x, e.pathTarget.y, tx, ty) > 60) {
1250:       e.pathT = 0.55;
1251:       e.pathTarget = { x: tx, y: ty };
1252:       e.path = this.map.findPath(e.x, e.y, tx, ty);
1253:     }
1254:     if (!e.path.length) {
1255:       e.angle = angleLerp(e.angle, Math.atan2(p.y - e.y, p.x - e.x), 1 - Math.exp(-4 * dt));
1256:       return;
1257:     }
1258:     let point = e.path[0];
1259:     if (dist(e.x, e.y, point.x, point.y) < 18) {
1260:       e.path.shift();
1261:       point = e.path[0];
1262:       if (!point) return;
1263:     }
1264:     const a = Math.atan2(point.y - e.y, point.x - e.x);
1265:     e.vx = damp(e.vx, Math.cos(a) * speed, 8, dt);
1266:     e.vy = damp(e.vy, Math.sin(a) * speed, 8, dt);
1267:     e.x += e.vx * dt;
1268:     e.y += e.vy * dt;
1269:     e.angle = angleLerp(e.angle, a, 1 - Math.exp(-7 * dt));
1270:     e.walk += dt * speed * 0.05;
1271:   }
1272: 
1273:   updateEnemyFire(e, d, dt) {
1274:     const p = this.player;
1275:     if (e.reloadT > 0) return;
1276:     if (e.mag <= 0) {
1277:       e.reloadT = e.type === 'heavy' ? 3.2 : 2.2;
1278:       e.mag = e.maxMag;
1279:       e.aimT = 0;
1280:       return;
1281:     }
1282:     if (e.aimT > 0) {
1283:       e.aimT -= dt;
1284:       e.angle = angleLerp(e.angle, Math.atan2(p.y - e.y, p.x - e.x), 1 - Math.exp(-10 * dt));
1285:       if (e.aimT <= 0) {
1286:         e.burstLeft = e.def.burst;
1287:         e.shotT = 0;
1288:       }
1289:       return;
1290:     }
1291:     if (e.burstLeft > 0) {
1292:       e.shotT -= dt;
1293:       if (e.shotT <= 0) {
1294:         this.enemyShoot(e, d);
1295:         e.burstLeft--;
1296:         e.shotT = 60 / e.def.rpm;
1297:         if (e.burstLeft <= 0) e.fireCd = e.def.burstGap + rand(0.2, 0.7);
1298:       }
1299:       return;
1300:     }
1301:     e.fireCd -= dt;
1302:     if (e.fireCd <= 0) e.aimT = e.def.aim;
1303:   }
1304: 
1305:   enemyShoot(e, d) {
1306:     const p = this.player;
1307:     e.mag--;
1308:     const moving = Math.hypot(p.vx, p.vy);
1309:     const spread = e.def.spread + moving * 0.006 + (e.type === 'marksman' ? 0.2 : 0.4);
1310:     const a = e.angle + deg((Math.random() - 0.5) * spread * 2);
1311:     const muzzleX = e.x + Math.cos(e.angle) * (e.r + 8);
1312:     const muzzleY = e.y + Math.sin(e.angle) * (e.r + 8);
1313:     const speed = e.def.bulletSpeed;
1314:     this.bullets.push({
1315:       x: muzzleX, y: muzzleY, vx: Math.cos(a) * speed, vy: Math.sin(a) * speed, speed,
1316:       dmg: e.def.dmg * rand(0.9, 1.1), pen: 1, owner: 'enemy', color: e.def.color,
1317:       life: 2.2, traveled: 0, ricochets: 0, tracer: true, angle: a, enemyType: e.type,
1318:     });
1319:     e.muzzleT = 0.06;
1320:     e.muzzleAngle = e.angle;
1321:     for (let i = 0; i < 3; i++) {
1322:       this.particles.push({
1323:         type: 'spark', x: muzzleX, y: muzzleY,
1324:         vx: Math.cos(e.angle + rand(-0.4, 0.4)) * rand(60, 180),
1325:         vy: Math.sin(e.angle + rand(-0.4, 0.4)) * rand(60, 180),
1326:         life: rand(0.06, 0.14), max: 0.14, size: rand(1, 2), color: e.def.accent,
1327:       });
1328:     }
1329:     const pan = this.renderer.panFor(muzzleX, muzzleY);
1330:     this.audio.shoot(e.type === 'marksman' ? 'dmr' : e.type === 'heavy' ? 'lmg' : 'rifle', { enemy: true, pan });
1331:   }
1332: 
1333:   // ------------------------------------------------------------------ bullets
1334:   updateBullets(dt) {
1335:     const p = this.player;
1336:     for (let i = this.bullets.length - 1; i >= 0; i--) {
1337:       const b = this.bullets[i];
1338:       b.life -= dt;
1339:       if (b.life <= 0) {
1340:         this.bullets.splice(i, 1);
1341:         continue;
1342:       }
1343:       const step = b.speed * dt;
1344:       if (step <= 0.01) continue;
1345:       const nx = b.vx / b.speed;
1346:       const ny = b.vy / b.speed;
1347:       const endX = b.x + nx * step;
1348:       const endY = b.y + ny * step;
1349:       const wallHit = this.map.raycast(b.x, b.y, endX, endY, step);
1350:       let actor = null;
1351:       let actorT = 1;
1352:       if (b.owner === 'player') {
1353:         for (const e of this.enemies) {
1354:           if (e.dead) continue;
1355:           const t = segCircle(b.x, b.y, endX, endY, e.x, e.y, e.r + 2);
1356:           if (t >= 0 && t < actorT) {
1357:             actorT = t;
1358:             actor = e;
1359:           }
1360:         }
1361:       } else if (p && !p.dead && p.invuln <= 0) {
1362:         const t = segCircle(b.x, b.y, endX, endY, p.x, p.y, p.r + 1);
1363:         if (t >= 0) {
1364:           actorT = t;
1365:           actor = p;
1366:         }
